      /\d{4}[.\-/]?\d{2}[.\-/]?\d{2}/
    );

    if (!match) {
      return null;
    }

    const digits = match[0].replace(/\D/g, '');

    if (digits.length !== 8) {
      return null;
    }

    return (
      digits.slice(0, 4) +
      '-' +
      digits.slice(4, 6) +
      '-' +
      digits.slice(6, 8)
    );
  })()
}}

