function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKC')
    .replace(/[^a-z0-9가-힣]/g, '');
}

return items.map(item => {
  const data = item.json;

  const normalizedTitle = normalizeText(data.title);
  const normalizedOrganization = normalizeText(data.organization);
  const normalizedDeadline = String(data.deadline || '')
    .replace(/\D/g, '');

  // 같은 출처 안에서 공고를 식별하는 고유키
  const sourceKey = `${data.source}:${data.notice_id}`;

  // 서로 다른 출처의 동일 공고 후보를 찾는 키
  // 마감일이 있으면 공고명+마감일,
  // 마감일이 없으면 공고명+기관명을 사용
  const dedupeKey = normalizedDeadline
    ? `${normalizedTitle}|${normalizedDeadline}`
    : `${normalizedTitle}|${normalizedOrganization}`;

  return {
    json: {
      ...data,
      source_key: sourceKey,
      dedupe_key: dedupeKey
    }
  };
});

const items = $input.all();

// 값이 비어 있는지 확인하는 함수
function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    value === '' ||
    (Array.isArray(value) && value.length === 0)
  );
}

// 설명형 필드는 더 자세하고 긴 값을 선택
function chooseLonger(first, second) {
  if (isEmpty(first)) return second;
  if (isEmpty(second)) return first;

  return String(second).length > String(first).length
    ? second
    : first;
}

// dedupe_key별로 공고 묶기
const groups = new Map();

for (const item of items) {
  const data = item.json;

  // dedupe_key가 없으면 다른 공고와 잘못 합쳐지지 않도록
  // source_key를 대신 사용
  const groupKey =
    data.dedupe_key ||
    data.source_key ||
    `${data.source}:${data.notice_id}`;

  if (!groups.has(groupKey)) {
    groups.set(groupKey, []);
  }

  groups.get(groupKey).push(data);
}

const results = [];

for (const [dedupeKey, records] of groups.entries()) {
  // 첫 번째 공고를 기본값으로 사용
  const merged = { ...records[0] };

  // 출처별 정보를 별도로 보관
  const sourceList = new Set();
  const sourceKeys = new Set();
  const noticeUrls = new Set();
  const applicationUrls = new Set();

  for (const record of records) {
    if (!isEmpty(record.source)) {
      sourceList.add(record.source);
    }

    if (!isEmpty(record.source_key)) {
      sourceKeys.add(record.source_key);
    }

    if (!isEmpty(record.url)) {
      noticeUrls.add(record.url);
    }

    if (!isEmpty(record.application_url)) {
      applicationUrls.add(record.application_url);
    }

    // 일반 필드: 기존 값이 비었을 때 다른 출처의 값으로 채움
    const fillIfEmptyFields = [
      'notice_id',
      'title',
      'organization',
      'published_at',
      'start_date',
      'deadline',
      'url',
      'application_url'
    ];

    for (const field of fillIfEmptyFields) {
      if (isEmpty(merged[field]) && !isEmpty(record[field])) {
        merged[field] = record[field];
      }
    }

    // 설명형 필드: 두 값 중 더 자세하고 긴 값을 선택
    const longerFields = [
      'target',
      'excluded_target',
      'region',
      'field',
      'application_method'
    ];

    for (const field of longerFields) {
      merged[field] = chooseLonger(
        merged[field],
        record[field]
      );
    }
  }

  merged.dedupe_key = dedupeKey;

  // 하나로 합쳐진 공고의 고유 식별값
  merged.canonical_key = dedupeKey;

  // 출처 및 원본 정보
  merged.source_list = [...sourceList];
  merged.source_keys = [...sourceKeys];
  merged.notice_urls = [...noticeUrls];
  merged.application_urls = [...applicationUrls];

  // 중복 여부
  merged.duplicate_count = records.length;
  merged.is_duplicate = records.length > 1;

  results.push({
    json: merged
  });
}

return results;

const items = $input.all();

const DAY_MS = 24 * 60 * 60 * 1000;

// 한국 기준 오늘 날짜 가져오기
function getKoreaToday() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Seoul',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());

  const values = {};

  for (const part of parts) {
    values[part.type] = part.value;
  }

  return `${values.year}-${values.month}-${values.day}`;
}

// 여러 날짜 형식을 UTC 자정 기준 숫자로 변환
function parseDate(value) {
  if (!value) return null;

  const text = String(value).trim();

  // 20260831 형식
  const compactMatch = text.match(
    /(?:^|\D)(\d{4})(\d{2})(\d{2})(?:\D|$)/
  );

  if (compactMatch) {
    return Date.UTC(
      Number(compactMatch[1]),
      Number(compactMatch[2]) - 1,
      Number(compactMatch[3])
    );
  }

  // 2026-08-31, 2026.08.31, 2026년 8월 31일
  const dateMatch = text.match(
    /(\d{4})\D+(\d{1,2})\D+(\d{1,2})/
  );

  if (!dateMatch) return null;

  return Date.UTC(
    Number(dateMatch[1]),
    Number(dateMatch[2]) - 1,
    Number(dateMatch[3])
  );
}

function formatDate(timestamp) {
  if (timestamp === null) return '';

  return new Date(timestamp)
    .toISOString()
    .slice(0, 10);
}

const today = parseDate(getKoreaToday());

return items.map(item => {
  const data = item.json;

  const originalStartDate = data.start_date || '';
  const originalDeadline = data.deadline || '';

  const startDate = parseDate(originalStartDate);
  const deadline = parseDate(originalDeadline);

  const dateText =
    `${originalStartDate} ${originalDeadline}`;

  const explicitlyAlwaysOpen =
    /상시\s*모집|상시\s*접수|상시/.test(dateText);

  let recruitmentStatus = 'unknown';
  let statusLabel = '일정 확인 필요';

  let daysUntilStart = null;
  let daysUntilDeadline = null;

  if (startDate !== null) {
    daysUntilStart = Math.floor(
      (startDate - today) / DAY_MS
    );
  }

  if (deadline !== null) {
    daysUntilDeadline = Math.floor(
      (deadline - today) / DAY_MS
    );
  }

  /*
   * 상태는 아래 조건 중 하나만 선택된다.
   * 위에서 선택되면 아래 조건은 실행되지 않는다.
   */

  // 1. 시작일이 마감일보다 늦으면 잘못된 날짜
  if (
    startDate !== null &&
    deadline !== null &&
    startDate > deadline
  ) {
    recruitmentStatus = 'unknown';
    statusLabel = '일정 확인 필요';
  }

  // 2. 시작일이 아직 오지 않음
  else if (
    startDate !== null &&
    daysUntilStart > 0
  ) {
    recruitmentStatus = 'upcoming';
    statusLabel = '모집 예정';
  }

  // 3. 마감일까지 8일 이상
  else if (
    deadline !== null &&
    daysUntilDeadline >= 8
  ) {
    recruitmentStatus = 'open';
    statusLabel = '모집 중';
  }

  // 4. 마감일까지 1~7일
  else if (
    deadline !== null &&
    daysUntilDeadline >= 1 &&
    daysUntilDeadline <= 7
  ) {
    recruitmentStatus = 'deadline_soon';
    statusLabel = `마감 임박 · D-${daysUntilDeadline}`;
  }

  // 5. 오늘 마감
  else if (
    deadline !== null &&
    daysUntilDeadline === 0
  ) {
    recruitmentStatus = 'due_today';
    statusLabel = '오늘 마감 · D-Day';
  }

  // 6. 이미 마감
  else if (
    deadline !== null &&
    daysUntilDeadline < 0
  ) {
    recruitmentStatus = 'closed';
    statusLabel = '마감';
  }

  // 7. 명시적 상시 모집 또는 시작일은 있지만 종료일 없음
  else if (
    explicitlyAlwaysOpen ||
    (startDate !== null && deadline === null)
  ) {
    recruitmentStatus = 'always_open';
    statusLabel = '상시 모집';
  }

  // 8. 나머지는 날짜 계산 불가
  else {
    recruitmentStatus = 'unknown';
    statusLabel = '일정 확인 필요';
  }

  return {
    json: {
      ...data,

      start_date:
        startDate !== null
          ? formatDate(startDate)
          : originalStartDate,

      deadline:
        deadline !== null
          ? formatDate(deadline)
          : originalDeadline,

      recruitment_status: recruitmentStatus,
      status_label: statusLabel,

      days_until_start: daysUntilStart,
      days_until_deadline: daysUntilDeadline,

      // 편리한 필터용 보조값
      is_deadline_soon:
        recruitmentStatus === 'deadline_soon',

      is_today_deadline:
        recruitmentStatus === 'due_today'
    }
  };
});

const title = String($json.title ?? '')
  .trim()
  .toLowerCase();

const content = String($json.content ?? '')
  .trim()
  .toLowerCase();

const rawUrl = String($json.url ?? '')
  .trim();

const lowerUrl = rawUrl.toLowerCase();

const score = Number($json.score ?? 0);

const text = `${title} ${content}`;


// --------------------------------------------------
// 1. URL에서 도메인 추출
// --------------------------------------------------

const hostname = lowerUrl
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split('/')[0]
  .split('?')[0]
  .split('#')[0]
  .split(':')[0];


// --------------------------------------------------
// 2. 지원사업 공고 관련 단어
// --------------------------------------------------

const positiveKeywords = [
  '모집',
  '모집공고',
  '지원사업',
  '지원 프로그램',
  '참여기업',
  '참가기업',
  '입주기업',
  '창업기업',
  '예비창업',
  '스타트업',
  '액셀러레이팅',
  '육성사업',
  '사업화 지원',
  '창업 지원',
  '참여자 모집',
  '신청 접수'
];


// --------------------------------------------------
// 3. 명백히 관계없는 모집 유형
// --------------------------------------------------

const negativeKeywords = [
  '신입생 모집',
  '입학전형',
  '채용공고',
  '직원 채용',
  '교원 채용',
  '부동산',
  '대출 광고',
  '쇼핑',
  '상품 구매'
];


// --------------------------------------------------
// 4. 직접 제공하지 않을 SNS·블로그·커뮤니티
// --------------------------------------------------

const blockedDomains = [
  'instagram.com',
  'facebook.com',
  'youtube.com',
  'youtu.be',
  'tiktok.com',
  'x.com',
  'twitter.com',

  'blog.naver.com',
  'm.blog.naver.com',
  'cafe.naver.com',
  'post.naver.com',

  'tistory.com',
  'brunch.co.kr',
  'velog.io',
  'medium.com',
  'blogspot.com',

  'dcinside.com',
  'fmkorea.com',
  'theqoo.net'
];


// --------------------------------------------------
// 5. 공식 원문을 찾는 단서로만 사용할 언론·포털
// --------------------------------------------------

const discoveryDomains = [
  'news.naver.com',
  'n.news.naver.com',
  'news.daum.net',
  'v.daum.net',

  'yna.co.kr',
  'newsis.com',
  'news1.kr',
  'mk.co.kr',
  'hankyung.com',
  'sedaily.com',
  'etnews.com',
  'zdnet.co.kr',

  'platum.kr',
  'venturesquare.net'
];


// --------------------------------------------------
// 6. 도메인과 관계없이 차단할 URL 경로
// --------------------------------------------------

const blockedUrlPatterns = [
  '/blog',
  '/blogs',
  '/cafe',
  '/community',
  '/magazine',
  '/column'
];


// --------------------------------------------------
// 7. 제목에 나타나는 비공식 콘텐츠 유형
// --------------------------------------------------

const blockedTitleKeywords = [
  '개인 블로그',
  '블로그 후기',
  '참여 후기',
  '신청 후기',
  '사용 후기',
  '체험 후기',
  '인터뷰',
  '칼럼',
  '리뷰'
];


// --------------------------------------------------
// 8. 도메인 목록 확인 함수
// --------------------------------------------------

const matchesDomain = (domainList) => {
  return domainList.find(domain =>
    hostname === domain ||
    hostname.endsWith(`.${domain}`)
  ) ?? null;
};


// --------------------------------------------------
// 9. 각 조건 검사
// --------------------------------------------------

const blockedDomain =
  matchesDomain(blockedDomains);

const discoveryDomain =
  matchesDomain(discoveryDomains);

const blockedUrlPattern =
  blockedUrlPatterns.find(pattern =>
    lowerUrl.includes(pattern)
  ) ?? null;

const blockedTitleKeyword =
  blockedTitleKeywords.find(keyword =>
    title.includes(keyword)
  ) ?? null;

const matchedPositiveKeywords =
  positiveKeywords.filter(keyword =>
    text.includes(keyword)
  );

const matchedNegativeKeywords =
  negativeKeywords.filter(keyword =>
    text.includes(keyword)
  );

const hasPositiveKeyword =
  matchedPositiveKeywords.length > 0;

const hasNegativeKeyword =
  matchedNegativeKeywords.length > 0;


// --------------------------------------------------
// 10. 공식기관 계열 도메인 확인
// --------------------------------------------------

const isGovernment =
  hostname.endsWith('.go.kr');

const isUniversity =
  hostname.endsWith('.ac.kr');

const isResearchInstitute =
  hostname.endsWith('.re.kr');

const isOrganization =
  hostname.endsWith('.or.kr');


// --------------------------------------------------
// 11. 최종 판정값 기본 설정
// --------------------------------------------------

let sourceType = '';
let trustLevel = '';
let candidateReason = '';

let isCandidate = false;
let discoveryOnly = false;
let needsVerification = false;


// --------------------------------------------------
// 12. 순서대로 공고 후보 판정
// --------------------------------------------------

if (!hostname) {
  sourceType = 'invalid_url';
  trustLevel = 'unusable';
  isCandidate = false;

  candidateReason =
    'URL 확인 불가';
}

else if (
  blockedDomain ||
  blockedUrlPattern ||
  blockedTitleKeyword
) {
  sourceType = 'blocked_platform';
  trustLevel = 'low';
  isCandidate = false;

  candidateReason =
    `블로그·SNS·커뮤니티·비공식 콘텐츠 제외: ${
      blockedDomain ||
      blockedUrlPattern ||
      blockedTitleKeyword
    }`;
}

else if (discoveryDomain) {
  sourceType = 'discovery_only';
  trustLevel = 'reference';

  isCandidate = false;
  discoveryOnly = true;

  candidateReason =
    `공식 원문 탐색용 참고자료: ${discoveryDomain}`;
}

else if (!hasPositiveKeyword) {
  sourceType = 'unrelated';
  trustLevel = 'low';
  isCandidate = false;

  candidateReason =
    '지원사업 공고 관련 핵심 단어 없음';
}

else if (hasNegativeKeyword) {
  sourceType = 'unrelated';
  trustLevel = 'low';
  isCandidate = false;

  candidateReason =
    `무관한 모집 유형: ${
      matchedNegativeKeywords.join(', ')
    }`;
}

else if (isGovernment) {
  sourceType = 'government';
  trustLevel = 'high';
  isCandidate = true;

  candidateReason =
    `정부·지자체 공식 도메인: ${hostname}`;
}

else if (isUniversity) {
  sourceType = 'university';
  trustLevel = 'high';
  isCandidate = true;

  candidateReason =
    `대학 공식 도메인: ${hostname}`;
}

else if (isResearchInstitute) {
  sourceType = 'research_institute';
  trustLevel = 'high';
  isCandidate = true;

  candidateReason =
    `연구기관 공식 도메인: ${hostname}`;
}

else if (isOrganization) {
  sourceType = 'organization_candidate';
  trustLevel = 'review';
  isCandidate = true;
  needsVerification = true;

  candidateReason =
    `기관 도메인 후보이며 원문 검증 필요: ${hostname}`;
}

else {
  // SNS·블로그·언론이 아닌 독립 도메인
  // 민간기업·재단·액셀러레이터 공식 홈페이지일 수 있음
  sourceType = 'private_official_candidate';
  trustLevel = 'review';
  isCandidate = true;
  needsVerification = true;

  candidateReason =
    `민간기관 자체 사이트 후보이며 원문 검증 필요: ${hostname}`;
}


// --------------------------------------------------
// 13. 기존 검색결과에 판정 필드 추가
// --------------------------------------------------

return {
  json: {
    ...$json,

    source_domain: hostname,
    source_type: sourceType,
    trust_level: trustLevel,

    is_candidate: isCandidate,
    discovery_only: discoveryOnly,
    needs_verification: needsVerification,

    candidate_reason: candidateReason,
    matched_keywords: matchedPositiveKeywords,
    search_score: score
  }
};

/*
 * DeepSeek JSON 응답 변환
 *
 * 역할:
 * 1. choices[0].message.content에서 응답 문자열 추출
 * 2. ```json 코드블록 제거
 * 3. JSON.parse()로 실제 JSON 객체 변환
 * 4. 날짜·출처·카테고리 필드 정리
 * 5. 파싱 성공 여부와 오류 사유 출력
 */

const response = $input.item.json;

/*
 * 1. DeepSeek 응답 본문 꺼내기
 */
const rawContent =
  response?.choices?.[0]?.message?.content ??
  '';

/*
 * 2. 원본 Tavily Extract 데이터 가져오기
 *
 * DeepSeek HTTP Request 노드는 응답만 출력하기 때문에
 * 원래 URL·제목·원문을 이전 노드에서 다시 가져온다.
 */
let previousData = {};

try {
  previousData =
    $('Tavily extract').item.json || {};
} catch (error) {
  previousData = {};
}

/*
 * Tavily Extract 결과가 results 배열 안에 있는 경우
 */
const previousResult =
  Array.isArray(previousData.results) &&
  previousData.results.length > 0
    ? previousData.results[0]
    : {};

/*
 * 3. 원래 공고 정보 정리
 */
const sourceUrl =
  previousResult.url ||
  previousData.url ||
  previousData.source_url ||
  previousData.discovery_url ||
  null;

const sourceTitle =
  previousResult.title ||
  previousData.title ||
  previousData.notice_title ||
  previousData.discovery_title ||
  null;

const sourceRawContent =
  previousResult.raw_content ||
  previousData.raw_content ||
  previousData.content ||
  previousData.description ||
  null;

/*
 * 4. 문자열 정리 함수
 */
function cleanText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const cleaned = String(value)
    .replace(/\s+/g, ' ')
    .trim();

  return cleaned || null;
}

/*
 * 5. Boolean 값 정리 함수
 *
 * DeepSeek가 true 대신 "true" 문자열을 반환하는 경우도 처리
 */
function normalizeBoolean(
  value,
  defaultValue = false
) {
  if (value === true) return true;
  if (value === false) return false;

  if (typeof value === 'string') {
    const normalized =
      value.trim().toLowerCase();

    if (normalized === 'true') {
      return true;
    }

    if (normalized === 'false') {
      return false;
    }
  }

  return defaultValue;
}

/*
 * 6. 배열 정리 함수
 */
function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return [];
  }

  return [value];
}

/*
 * 7. DeepSeek가 반환한 코드블록 제거
 *
 * 예:
 * ```json
 * { ... }
 * ```
 */
function removeMarkdownCodeFence(value) {
  return String(value || '')
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

/*
 * 8. JSON 객체 부분만 추출
 *
 * DeepSeek가 JSON 앞뒤에 설명을 붙여도
 * 첫 번째 { 부터 마지막 } 까지만 가져온다.
 */
function extractJsonObject(value) {
  const text = removeMarkdownCodeFence(value);

  const firstBrace =
    text.indexOf('{');

  const lastBrace =
    text.lastIndexOf('}');

  if (
    firstBrace === -1 ||
    lastBrace === -1 ||
    lastBrace < firstBrace
  ) {
    throw new Error(
      'DeepSeek 응답에서 JSON 객체를 찾을 수 없습니다.'
    );
  }

  return text.substring(
    firstBrace,
    lastBrace + 1
  );
}

/*
 * 9. 지원유형 허용값
 */
const STANDARD_CATEGORIES = [
  '사업화',
  '기술개발(R&D)',
  '시설·공간·보육',
  '멘토링·컨설팅·교육',
  '글로벌',
  '인력',
  '융자·보증',
  '행사·네트워크',
  '창업교육',
  '판로·해외진출',
  '정책자금',
  '기타'
];

/*
 * 10. 허용된 notice_type
 */
const ALLOWED_NOTICE_TYPES = [
  'individual_recruitment',
  'integrated_announcement',
  'list_page',
  'information_page',
  'news_article',
  'repost',
  'inaccessible',
  'unknown'
];

/*
 * 11. 허용된 source_role
 */
const ALLOWED_SOURCE_ROLES = [
  'primary_official',
  'authorized_application',
  'secondary_repost',
  'news_or_reference',
  'blocked_source',
  'unknown'
];

/*
 * 12. 허용된 신뢰도
 */
const ALLOWED_CONFIDENCE = [
  'high',
  'medium',
  'low'
];

/*
 * 13. JSON 파싱
 */
let parsed = null;
let parseSuccess = false;
let parseError = null;
let cleanedJsonText = null;

try {
  cleanedJsonText =
    extractJsonObject(rawContent);

  parsed =
    JSON.parse(cleanedJsonText);

  parseSuccess = true;
} catch (error) {
  parseSuccess = false;

  parseError =
    error?.message ||
    '알 수 없는 JSON 변환 오류';
}

/*
 * 14. 파싱 실패 시 오류 정보를 반환
 *
 * 워크플로우 전체를 중단하지 않고
 * 이후 검토할 수 있도록 데이터로 반환함.
 */
if (!parseSuccess || !parsed) {
  return {
    json: {
      source_url:
        sourceUrl,

      source_title:
        sourceTitle,

      raw_content:
        sourceRawContent,

      parse_success:
        false,

      parse_error:
        parseError,

      deepseek_raw_content:
        rawContent,

      deepseek_model:
        response?.model ?? null,

      deepseek_usage:
        response?.usage ?? null,

      is_actual_notice:
        false,

      notice_type:
        'unknown',

      source_role:
        'unknown',

      is_official_source:
        false,

      needs_official_source_search:
        true,

      primary_category:
        null,

      support_categories:
        [],

      other_category_description:
        null,

      category_evidence:
        [],

      category_confidence:
        'low',

      category_parse_success:
        false,

      category_needs_review:
        true
    }
  };
}

/*
 * 15. notice_type 정리
 */
const noticeType =
  ALLOWED_NOTICE_TYPES.includes(
    parsed.notice_type
  )
    ? parsed.notice_type
    : 'unknown';

/*
 * 16. source_role 정리
 */
const sourceRole =
  ALLOWED_SOURCE_ROLES.includes(
    parsed.source_role
  )
    ? parsed.source_role
    : 'unknown';

/*
 * 17. 지원유형 배열 정리
 */
const rawCategories =
  normalizeArray(
    parsed.support_categories
  );

const supportCategories = [
  ...new Set(
    rawCategories
      .map(category =>
        cleanText(category)
      )
      .filter(category =>
        STANDARD_CATEGORIES.includes(
          category
        )
      )
  )
];

/*
 * 18. 대표 카테고리 정리
 */
let primaryCategory =
  cleanText(
    parsed.primary_category
  );

if (
  !STANDARD_CATEGORIES.includes(
    primaryCategory
  )
) {
  primaryCategory = null;
}

/*
 * 대표 카테고리가 배열에 없다면
 * 배열의 첫 번째 항목을 대표값으로 사용
 */
if (
  primaryCategory &&
  !supportCategories.includes(
    primaryCategory
  )
) {
  supportCategories.unshift(
    primaryCategory
  );
}

if (
  !primaryCategory &&
  supportCategories.length > 0
) {
  primaryCategory =
    supportCategories[0];
}

/*
 * 19. 기타 설명 정리
 */
const otherCategoryDescription =
  supportCategories.includes('기타')
    ? cleanText(
        parsed.other_category_description
      )
    : null;

/*
 * 20. 카테고리 근거 정리
 */
const rawCategoryEvidence =
  normalizeArray(
    parsed.category_evidence
  );

const categoryEvidence =
  rawCategoryEvidence
    .map(item => {
      if (
        !item ||
        typeof item !== 'object'
      ) {
        return null;
      }

      const category =
        cleanText(item.category);

      const evidence =
        cleanText(item.evidence);

      if (
        !category ||
        !evidence ||
        !STANDARD_CATEGORIES.includes(
          category
        )
      ) {
        return null;
      }

      return {
        category,
        evidence
      };
    })
    .filter(Boolean);

/*
 * 21. 카테고리 신뢰도 정리
 */
const categoryConfidence =
  ALLOWED_CONFIDENCE.includes(
    parsed.category_confidence
  )
    ? parsed.category_confidence
    : 'low';

/*
 * 22. 카테고리 검토 필요 여부
 */
const categoryParseSuccess =
  supportCategories.length > 0;

const categoryNeedsReview =
  supportCategories.length === 0 ||
  categoryConfidence === 'low' ||
  (
    supportCategories.includes('기타') &&
    !otherCategoryDescription
  );

/*
 * 23. 공식 출처 여부 정리
 *
 * source_role 값을 기준으로 한 번 더 안전하게 계산
 */
const isOfficialSource =
   sourceRole === 'primary_official' ||
  sourceRole === 'authorized_application';

/*
 * 24. 원문 재검색 필요 여부
 */
let needsOfficialSourceSearch = false;

if (
  sourceRole === 'secondary_repost' ||
  sourceRole === 'news_or_reference' ||
  sourceRole === 'unknown'
) {
  needsOfficialSourceSearch = true;
}

/*
 * 25. 날짜·시간 필드 정리
 */
const startDate =
  cleanText(parsed.start_date);

const startTime =
  cleanText(parsed.start_time);

const startAt =
  cleanText(parsed.start_at);

const deadline =
  cleanText(parsed.deadline);

const deadlineTime =
  cleanText(parsed.deadline_time);

const deadlineAt =
  cleanText(parsed.deadline_at);

/*
 * 26. 최종 출력
 */
return {
  json: {
    /*
     * 원래 Tavily Extract 데이터
     */
    source_url:
      sourceUrl,

    url:
      sourceUrl,

    source_title:
      sourceTitle,

    raw_content:
      sourceRawContent,

    /*
     * JSON 변환 상태
     */
    parse_success:
      true,

    parse_error:
      null,

    /*
     * 공고 기본 판정
     */
    is_actual_notice:
      normalizeBoolean(
        parsed.is_actual_notice,
        false
      ),

    notice_type:
      noticeType,

    source_role:
      sourceRole,

    is_official_source:
      isOfficialSource,

    needs_official_source_search:
      needsOfficialSourceSearch,

    validation_reason:
      cleanText(
        parsed.validation_reason
      ),

    /*
     * 공고 기본정보
     */
    title:
      cleanText(parsed.title) ||
      sourceTitle,

    organization:
      cleanText(
        parsed.organization
      ),

    target:
      cleanText(
        parsed.target
      ),

    support_summary:
      cleanText(
        parsed.support_summary
      ),

    region:
      cleanText(
        parsed.region
      ),

    /*
     * 모집 일정
     */
    start_date:
      startDate,

    start_time:
      startTime,

    start_at:
      startAt,

    deadline:
      deadline,

    deadline_time:
      deadlineTime,

    deadline_at:
      deadlineAt,

    start_original_text:
      cleanText(
        parsed.start_original_text
      ),

    deadline_original_text:
      cleanText(
        parsed.deadline_original_text
      ),

    is_rolling_recruitment:
      normalizeBoolean(
        parsed.is_rolling_recruitment,
        false
      ),

    schedule_needs_review:
      normalizeBoolean(
        parsed.schedule_needs_review,
        false
      ),

    /*
     * 신청방법
     */
    application_method:
      cleanText(
        parsed.application_method
      ),

    application_url:
      cleanText(
        parsed.application_url
      ),

    /*
     * 지원유형
     */
    primary_category:
      primaryCategory,

    support_categories:
      supportCategories,

    other_category_description:
      otherCategoryDescription,

    category_evidence:
      categoryEvidence,

    category_confidence:
      categoryConfidence,

    category_parse_success:
      categoryParseSuccess,

    category_needs_review:
      categoryNeedsReview,

    /*
     * DeepSeek 실행정보
     */
    deepseek_model:
      response?.model ?? null,

    deepseek_usage:
      response?.usage ?? null,

    deepseek_raw_content:
      rawContent
  }
};

const inputItems = $input.all();
const outputItems = [];

// 검색어에서 제거할 지나치게 일반적인 단어
const stopwords = new Set([
  '공고',
  '모집',
  '모집공고',
  '지원',
  '지원사업',
  '사업',
  '신청',
  '접수',
  '안내',
  '알림',
  '알림마당',
  '사업공고',
  '참여',
  '대상',
  '공식',
  '홈페이지'
]);

function cleanText(value) {
  return String(value || '')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/[|｜:·•〈〉《》「」『』()]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getDomain(url) {
  try {
    return new URL(String(url || ''))
      .hostname
      .toLowerCase()
      .replace(/^www\./, '');
  } catch (error) {
    return '';
  }
}

for (const item of inputItems) {
  const data = item.json;

  const title = cleanText(data.title);
  const organization = cleanText(data.organization);

  const discoveryUrl = String(
    data.url ||
    data.discovery_url ||
    ''
  ).trim();

  const discoveryDomain = getDomain(discoveryUrl);

  // 제목에서 연도 추출
  const yearMatch = title.match(/20\d{2}년?/);
  const year = yearMatch ? yearMatch[0] : '';

  // 제목을 띄어쓰기 단위로 분리하여 핵심 키워드 생성
  const titleTokens = title
    .split(' ')
    .map(token => token.trim())
    .filter(token => token.length >= 2)
    .filter(token => !stopwords.has(token))
    .filter(token => !/^20\d{2}년?$/.test(token));

  // 중복 단어 제거
  const uniqueTokens = [...new Set(titleTokens)];

  // 너무 많은 단어를 사용하지 않도록 최대 7개만 사용
  const coreKeywords = uniqueTokens
    .slice(0, 7)
    .join(' ');

  const queries = [];

  // 검색어 1: 제목 중심
  if (title) {
    queries.push({
      variant: 'title',
      query: `${title} 공식 공고 원문`
    });
  }

  // 검색어 2: 연도와 핵심 키워드 중심
  if (coreKeywords) {
    queries.push({
      variant: 'keywords',
      query: [
        year,
        coreKeywords,
        '모집 신청'
      ]
        .filter(Boolean)
        .join(' ')
    });
  }

  // 검색어 3: 핵심 키워드와 기관명 중심
  if (coreKeywords || organization) {
    queries.push({
      variant: 'organization',
      query: [
        coreKeywords,
        organization,
        '공식 지원사업 공고'
      ]
        .filter(Boolean)
        .join(' ')
    });
  }

  // 완전히 동일한 검색어가 생기면 하나만 남김
  const uniqueQueries = [];

  for (const queryItem of queries) {
    const normalizedQuery = queryItem.query
      .replace(/\s+/g, ' ')
      .trim();

    const alreadyExists = uniqueQueries.some(
      existing => existing.query === normalizedQuery
    );

    if (!alreadyExists && normalizedQuery) {
      uniqueQueries.push({
        ...queryItem,
        query: normalizedQuery
      });
    }
  }

  // 검색어 하나를 n8n Item 하나로 분리
  for (const queryItem of uniqueQueries) {
    outputItems.push({
      json: {
        ...data,

        discovery_url: discoveryUrl,
        discovery_domain: discoveryDomain,

        original_notice_title: title,
        original_organization: organization,

        extracted_year: year,
        extracted_core_keywords: uniqueTokens.slice(0, 7),

        official_search_query: queryItem.query,
        search_query_variant: queryItem.variant,

        official_search_attempt: 1
      }
    });
  }
}

return outputItems;

const inputData = $input.item.json;
const resultData = inputData.results || {};

const url = String(resultData.url || '').trim();
const title = String(resultData.title || '').trim();
const rawContent = String(resultData.content || '').trim();
const score = Number(resultData.score || 0);

// \uBAA9 같은 형태로 들어온 한글 복원
function decodeEscapedText(text) {
  return String(text || '')
    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) =>
      String.fromCharCode(parseInt(hex, 16))
    )
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '')
    .replace(/\\t/g, ' ')
    .replace(/\\"/g, '"');
}

const content = decodeEscapedText(rawContent);

// new URL()을 사용하지 않고 도메인 추출
function extractDomain(value) {
  const match = String(value || '').match(
    /^https?:\/\/([^/?#]+)/i
  );

  if (!match) {
    return '';
  }

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .replace(/:\d+$/, '');
}

// URL 경로 추출
function extractPathname(value) {
  const match = String(value || '').match(
    /^https?:\/\/[^/?#]+([^?#]*)/i
  );

  if (!match) {
    return '';
  }

  return String(match[1] || '').toLowerCase();
}

const domain = extractDomain(url);
const pathname = extractPathname(url);

// SNS·개인 블로그·커뮤니티
const blockedDomains = [
  'instagram.com',
  'youtube.com',
  'youtu.be',
  'facebook.com',
  'tiktok.com',
  'x.com',
  'twitter.com',

  'blog.naver.com',
  'cafe.naver.com',
  'post.naver.com',

  'brunch.co.kr',
  'tistory.com',

  'dcinside.com',
  'fmkorea.com',
  'theqoo.net'
];

const isBlockedDomain = blockedDomains.some(blocked =>
  domain === blocked || domain.endsWith(`.${blocked}`)
);

const blockedPathPatterns = [
  '/blog/',
  '/blogs/',
  '/cafe/',
  '/community/'
];

const isBlockedPath = blockedPathPatterns.some(pattern =>
  pathname.includes(pattern)
);

// 뉴스·기사·보도자료 경로
const newsPathPatterns = [
  '/news/',
  '/article/',
  '/articles/',
  '/press/'
];

const isNewsPath = newsPathPatterns.some(pattern =>
  pathname.includes(pattern)
);

// 지원사업 공고 관련 키워드
const combinedText = `${title} ${content}`.toLowerCase();

const noticeKeywords = [
  '모집',
  '공고',
  '지원사업',
  '지원 사업',
  '참여기업',
  '참여 기업',
  '참여자',
  '신청',
  '접수',
  '창업지원',
  '창업 지원',
  '사업화',
  '입주기업',
  '입주 기업',
  '교육생 모집'
];

const matchedKeywords = noticeKeywords.filter(keyword =>
  combinedText.includes(keyword)
);

const hasNoticeKeyword = matchedKeywords.length > 0;

// 정부·대학·연구기관·비영리기관 도메인
const isInstitutionDomain =
  domain.endsWith('.go.kr') ||
  domain.endsWith('.ac.kr') ||
  domain.endsWith('.re.kr') ||
  domain.endsWith('.or.kr');

// 대표적인 공식 지원사업 사이트
const knownOfficialDomains = [
  'k-startup.go.kr',
  'bizinfo.go.kr',
  'mss.go.kr'
];

const isKnownOfficialDomain = knownOfficialDomains.some(official =>
  domain === official || domain.endsWith(`.${official}`)
);

let is_official_candidate = false;
let official_candidate_level = 'reject';
let official_candidate_reason = '';

// 판정 시작
if (!url) {
  official_candidate_reason = '검색 결과에 URL 값이 없음';
}

else if (!domain) {
  official_candidate_reason = 'URL 형식을 해석할 수 없음';
}

else if (isBlockedDomain || isBlockedPath) {
  official_candidate_reason = 'SNS·블로그·커뮤니티 출처';
}

else if (!hasNoticeKeyword) {
  official_candidate_reason =
    '지원사업 모집공고 관련 단어 부족';
}

else if (score < 0.35) {
  official_candidate_reason =
    'Tavily 검색 관련도 점수 부족';
}

else if (isKnownOfficialDomain || isInstitutionDomain) {
  is_official_candidate = true;
  official_candidate_level = 'high';
  official_candidate_reason =
    '공식기관 도메인의 모집공고 후보';
}

else if (isNewsPath) {
  official_candidate_reason =
    '기사·보도자료 형태의 페이지';
}

else {
  is_official_candidate = true;
  official_candidate_level = 'review';
  official_candidate_reason =
    '민간 운영기관 공식 페이지 가능성 — 원문 검증 필요';
}

return {
  json: {
    ...inputData,

    // results 내부 값을 바깥으로 꺼냄
    url,
    title,
    content,
    score,

    // 판정 결과
    source_domain: domain,
    source_pathname: pathname,

    is_official_candidate,
    official_candidate_level,
    official_candidate_reason,

    matched_notice_keywords: matchedKeywords,
    tavily_search_score: score
  }
};

const data = $input.item.json;

/*
 * HTTP/HTML 노드를 지나면서 원래 재게시 URL이
 * 사라진 경우 앞 노드에서 다시 가져온다.
 */
let upstreamData = {};

try {
  upstreamData =
    $('재게시 원문 재검색 필터').item.json || {};
} catch {
  upstreamData = {};
}

/*
 * 현재 검토하는 재게시 페이지 주소
 */
const sourceUrl = String(
  data.repost_source_url ||
  data.discovery_source_url ||
  data.source_url ||
  data.url ||
  upstreamData.repost_source_url ||
  upstreamData.discovery_source_url ||
  upstreamData.source_url ||
  upstreamData.url ||
  ''
).trim();

/*
 * 배열·중첩 배열·객체에서 URL 문자열을 꺼낸다.
 */
function flattenUrlValues(value) {
  if (value === null || value === undefined) {
    return [];
  }

  if (Array.isArray(value)) {
    return value.flatMap(item =>
      flattenUrlValues(item)
    );
  }

  if (typeof value === 'object') {
    const objectUrl =
      value.href ||
      value.url ||
      value.value ||
      value.link ||
      '';

    return objectUrl
      ? flattenUrlValues(objectUrl)
      : [];
  }

  return [String(value).trim()];
}

/*
 * 링크 문구 배열 평탄화
 */
function flattenTextValues(value) {
  if (value === null || value === undefined) {
    return [];
  }

  if (Array.isArray(value)) {
    return value.flatMap(item =>
      flattenTextValues(item)
    );
  }

  if (typeof value === 'object') {
    const objectText =
      value.text ||
      value.label ||
      value.title ||
      value.value ||
      '';

    return objectText
      ? flattenTextValues(objectText)
      : [];
  }

  return [String(value).trim()];
}

const linkUrls =
  flattenUrlValues(data.link_urls);

const linkTexts =
  flattenTextValues(data.link_texts);

/*
 * new URL()을 사용하지 않고
 * 상대주소를 절대주소로 변환한다.
 */
function makeAbsoluteUrl(link, baseUrl) {
  let value = String(link || '')
    .trim()
    .replace(/&amp;/gi, '&');

  if (!value) {
    return '';
  }

  /*
   * 웹페이지 주소가 아닌 값 제외
   */
  if (
    value.startsWith('#') ||
    /^javascript:/i.test(value) ||
    /^mailto:/i.test(value) ||
    /^tel:/i.test(value) ||
    /^data:/i.test(value)
  ) {
    return '';
  }

  /*
   * 이미 완전한 HTTP 주소면 그대로 사용
   */
  if (/^https?:\/\//i.test(value)) {
    return value;
  }

  /*
   * //example.com/path
   */
  if (value.startsWith('//')) {
    return `https:${value}`;
  }

  /*
   * 상대주소인데 기준 주소가 없으면 변환 불가
   */
  if (!baseUrl) {
    return '';
  }

  /*
   * https://example.com 부분 추출
   */
  const originMatch =
    String(baseUrl).match(
      /^(https?:\/\/[^/]+)/i
    );

  if (!originMatch) {
    return '';
  }

  const origin = originMatch[1];

  /*
   * /apply와 같은 루트 상대주소
   */
  if (value.startsWith('/')) {
    return `${origin}${value}`;
  }

  /*
   * apply와 같은 현재 폴더 기준 상대주소
   */
  const baseWithoutQuery = String(baseUrl)
    .split('?')[0]
    .split('#')[0];

  const lastSlashIndex =
    baseWithoutQuery.lastIndexOf('/');

  const baseDirectory =
    lastSlashIndex >= 0
      ? baseWithoutQuery.substring(
          0,
          lastSlashIndex + 1
        )
      : `${origin}/`;

  return `${baseDirectory}${value}`;
}

/*
 * 정규식으로 도메인 추출
 *
 * www.k-startup.go.kr
 * →
 * k-startup.go.kr
 */
function getDomain(url) {
  const match = String(url || '').match(
    /^https?:\/\/([^/:?#]+)/i
  );

  if (!match) {
    return '';
  }

  return match[1]
    .replace(/^www\./i, '')
    .toLowerCase();
}

function normalizeUrl(url) {
  return String(url || '')
    .trim()
    .replace(/&amp;/gi, '&')
    .replace(/#.*$/, '')
    .replace(/\/$/, '')
    .toLowerCase();
}

function normalizeText(text) {
  return String(text || '')
    .toLowerCase()
    .replace(
      /[\s·ㆍ・|>→▶▷►➜➡️\-_/()[\]{}:：,.!?'"“”‘’]/g,
      ''
    );
}

/*
 * 같은 도메인 또는 하위 도메인인지 확인
 */
function isSameSite(firstDomain, secondDomain) {
  if (!firstDomain || !secondDomain) {
    return false;
  }

  return (
    firstDomain === secondDomain ||
    firstDomain.endsWith(`.${secondDomain}`) ||
    secondDomain.endsWith(`.${firstDomain}`)
  );
}

function findMatchedValues(
  text,
  searchValues
) {
  const normalizedText =
    normalizeText(text);

  return searchValues.filter(value =>
    normalizedText.includes(
      normalizeText(value)
    )
  );
}

function unique(values) {
  return [...new Set(values)];
}

