  if (isTrustedInstitutionDomain) {
    score += 60;
    evidence.push(
      'institution_domain'
    );
  }

  /*
   * 부정 표현은 감점만 적용
   */
  if (
    matchedNegativeWords.length > 0
  ) {
    score -= Math.min(
      matchedNegativeWords.length * 40,
      160
    );

    evidence.push(
      `negative_words:${matchedNegativeWords.join(',')}`
    );
  }

  let candidateType =
    'external_link_candidate';

  if (
    hasOfficialPhrase ||
    (
      hasSourceSignal &&
      hasNoticeSignal
    )
  ) {
    candidateType =
      'official_source_candidate';
  } else if (
    hasNoticePhrase ||
    hasNoticeSignal ||
    hasNoticeUrl
  ) {
    candidateType =
      'notice_candidate';
  } else if (
    hasApplicationPhrase ||
    hasApplicationSignal ||
    hasApplicationUrl
  ) {
    candidateType =
      'application_candidate';
  }

  seenCandidateUrls.add(
    normalizedCandidateUrl
  );

  candidates.push({
    url: absoluteUrl,
