const response = $input.item.json;

/*
 * 1. DeepSeek 응답 본문 꺼내기
 */
const rawContent =
  response?.choices?.[0]?.message?.content ??
  '';

/*
 * 2. 원본 Tavily Extract 데이터 가져오기
 *
 * DeepSeek HTTP Request 노드는 응답만 출력하기 때문에
 * 원래 URL·제목·원문을 이전 노드에서 다시 가져온다.
 */
let previousData = {};

try {
  previousData =
    $('Tavily extract').item.json || {};
} catch (error) {
  previousData = {};
}

/*
 * Tavily Extract 결과가 results 배열 안에 있는 경우
 */
const previousResult =
  Array.isArray(previousData.results) &&
  previousData.results.length > 0
    ? previousData.results[0]
    : {};

/*
 * 3. 원래 공고 정보 정리
 */
const sourceUrl =
  previousResult.url ||
  previousData.url ||
  previousData.source_url ||
  previousData.discovery_url ||
  null;

const sourceTitle =
  previousResult.title ||
  previousData.title ||
  previousData.notice_title ||
  previousData.discovery_title ||
  null;

const sourceRawContent =
  previousResult.raw_content ||
  previousData.raw_content ||
  previousData.content ||
  previousData.description ||
  null;

/*
 * 4. 문자열 정리 함수
 */
function cleanText(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  const cleaned = String(value)
    .replace(/\s+/g, ' ')
    .trim();

  return cleaned || null;
}

/*
 * 5. Boolean 값 정리 함수
 *
 * DeepSeek가 true 대신 "true" 문자열을 반환하는 경우도 처리
 */
function normalizeBoolean(
  value,
  defaultValue = false
) {
  if (value === true) return true;
  if (value === false) return false;

  if (typeof value === 'string') {
    const normalized =
      value.trim().toLowerCase();

    if (normalized === 'true') {
      return true;
    }

    if (normalized === 'false') {
      return false;
    }
  }

  return defaultValue;
}

/*
 * 6. 배열 정리 함수
 */
function normalizeArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return [];
  }

  return [value];
}

/*
 * 7. DeepSeek가 반환한 코드블록 제거
 *
 * 예:
 * ```json
 * { ... }
 * ```
 */
function removeMarkdownCodeFence(value) {
  return String(value || '')
    .replace(/^\s*```json\s*/i, '')
    .replace(/^\s*```\s*/i, '')
    .replace(/\s*```\s*$/i, '')
    .trim();
}

/*
 * 8. JSON 객체 부분만 추출
 *
 * DeepSeek가 JSON 앞뒤에 설명을 붙여도
 * 첫 번째 { 부터 마지막 } 까지만 가져온다.
 */
function extractJsonObject(value) {
  const text = removeMarkdownCodeFence(value);

  const firstBrace =
    text.indexOf('{');

  const lastBrace =
    text.lastIndexOf('}');

  if (
    firstBrace === -1 ||
    lastBrace === -1 ||
    lastBrace < firstBrace
  ) {
    throw new Error(
      'DeepSeek 응답에서 JSON 객체를 찾을 수 없습니다.'
    );
  }

  return text.substring(
    firstBrace,
    lastBrace + 1
  );
}

/*
 * 9. 지원유형 허용값
 */
const STANDARD_CATEGORIES = [
  '사업화',
  '기술개발(R&D)',
  '시설·공간·보육',
  '멘토링·컨설팅·교육',
  '글로벌',
  '인력',
  '융자·보증',
  '행사·네트워크',
  '창업교육',
  '판로·해외진출',
  '정책자금',
  '기타'
];

/*
 * 10. 허용된 notice_type
 */
const ALLOWED_NOTICE_TYPES = [
  'individual_recruitment',
  'integrated_announcement',
  'list_page',
  'information_page',
  'news_article',
  'repost',
  'inaccessible',
  'unknown'
];

/*
 * 11. 허용된 source_role
 */
const ALLOWED_SOURCE_ROLES = [
  'primary_official',
  'authorized_application',
  'secondary_repost',
  'news_or_reference',
  'blocked_source',
  'unknown'
];

/*
 * 12. 허용된 신뢰도
 */
const ALLOWED_CONFIDENCE = [
  'high',
  'medium',
  'low'
];

/*
 * 13. JSON 파싱
 */
let parsed = null;
let parseSuccess = false;
let parseError = null;
let cleanedJsonText = null;

try {
  cleanedJsonText =
    extractJsonObject(rawContent);

  parsed =
    JSON.parse(cleanedJsonText);

  parseSuccess = true;
} catch (error) {
  parseSuccess = false;

  parseError =
    error?.message ||
    '알 수 없는 JSON 변환 오류';
}

/*
 * 14. 파싱 실패 시 오류 정보를 반환
 *
 * 워크플로우 전체를 중단하지 않고
 * 이후 검토할 수 있도록 데이터로 반환함.
 */
if (!parseSuccess || !parsed) {
  return {
    json: {
      source_url:
        sourceUrl,

      source_title:
        sourceTitle,

      raw_content:
        sourceRawContent,

      parse_success:
        false,

      parse_error:
        parseError,

      deepseek_raw_content:
        rawContent,

      deepseek_model:
        response?.model ?? null,

      deepseek_usage:
        response?.usage ?? null,

      is_actual_notice:
        false,

      notice_type:
        'unknown',

      source_role:
        'unknown',

      is_official_source:
        false,

      needs_official_source_search:
        true,

      primary_category:
        null,

      support_categories:
        [],

      other_category_description:
        null,

      category_evidence:
        [],

      category_confidence:
        'low',

      category_parse_success:
        false,

      category_needs_review:
        true
    }
  };
}

/*
 * 15. notice_type 정리
 */
const noticeType =
  ALLOWED_NOTICE_TYPES.includes(
    parsed.notice_type
  )
    ? parsed.notice_type
    : 'unknown';

/*
 * 16. source_role 정리
 */
const sourceRole =
  ALLOWED_SOURCE_ROLES.includes(
    parsed.source_role
  )
    ? parsed.source_role
    : 'unknown';

/*
 * 17. 지원유형 배열 정리
 */
const rawCategories =
  normalizeArray(
    parsed.support_categories
  );

const supportCategories = [
  ...new Set(
    rawCategories
      .map(category =>
        cleanText(category)
      )
      .filter(category =>
        STANDARD_CATEGORIES.includes(
          category
        )
      )
  )
];

/*
 * 18. 대표 카테고리 정리
 */
let primaryCategory =
  cleanText(
    parsed.primary_category
  );

if (
  !STANDARD_CATEGORIES.includes(
    primaryCategory
  )
) {
  primaryCategory = null;
}

/*
 * 대표 카테고리가 배열에 없다면
 * 배열의 첫 번째 항목을 대표값으로 사용
 */
if (
  primaryCategory &&
  !supportCategories.includes(
    primaryCategory
  )
) {
  supportCategories.unshift(
    primaryCategory
  );
}

if (
  !primaryCategory &&
  supportCategories.length > 0
) {
  primaryCategory =
    supportCategories[0];
}

/*
 * 19. 기타 설명 정리
 */
const otherCategoryDescription =
  supportCategories.includes('기타')
    ? cleanText(
        parsed.other_category_description
      )
    : null;

/*
 * 20. 카테고리 근거 정리
 */
const rawCategoryEvidence =
  normalizeArray(
    parsed.category_evidence
  );

const categoryEvidence =
  rawCategoryEvidence
    .map(item => {
      if (
        !item ||
        typeof item !== 'object'
      ) {
        return null;
      }

      const category =
        cleanText(item.category);

      const evidence =
        cleanText(item.evidence);

      if (
        !category ||
        !evidence ||
        !STANDARD_CATEGORIES.includes(
          category
        )
      ) {
        return null;
      }

      return {
        category,
        evidence
      };
    })
    .filter(Boolean);

/*
 * 21. 카테고리 신뢰도 정리
 */
const categoryConfidence =
  ALLOWED_CONFIDENCE.includes(
    parsed.category_confidence
  )
    ? parsed.category_confidence
    : 'low';

/*
 * 22. 카테고리 검토 필요 여부
 */
const categoryParseSuccess =
  supportCategories.length > 0;

const categoryNeedsReview =
  supportCategories.length === 0 ||
  categoryConfidence === 'low' ||
  (
    supportCategories.includes('기타') &&
    !otherCategoryDescription
  );

/*
 * 23. 공식 출처 여부 정리
 *
 * source_role 값을 기준으로 한 번 더 안전하게 계산
 */
const isOfficialSource =
   sourceRole === 'primary_official' ||
  sourceRole === 'authorized_application';

/*
 * 24. 원문 재검색 필요 여부
 */
let needsOfficialSourceSearch = false;

if (
  sourceRole === 'secondary_repost' ||
  sourceRole === 'news_or_reference' ||
  sourceRole === 'unknown'
) {
  needsOfficialSourceSearch = true;
}

/*
 * 25. 날짜·시간 필드 정리
 */
const startDate =
  cleanText(parsed.start_date);

const startTime =
  cleanText(parsed.start_time);

const startAt =
  cleanText(parsed.start_at);

const deadline =
  cleanText(parsed.deadline);

const deadlineTime =
  cleanText(parsed.deadline_time);

const deadlineAt =
  cleanText(parsed.deadline_at);

/*
 * 26. 최종 출력
 */
return {
  json: {
    /*
     * 원래 Tavily Extract 데이터
     */
    source_url:
      sourceUrl,

    url:
      sourceUrl,

    source_title:
      sourceTitle,

    raw_content:
      sourceRawContent,

    /*
     * JSON 변환 상태
     */
    parse_success:
      true,

    parse_error:
      null,

    /*
     * 공고 기본 판정
     */
    is_actual_notice:
      normalizeBoolean(
        parsed.is_actual_notice,
        false
      ),

    notice_type:
      noticeType,

    source_role:
      sourceRole,

    is_official_source:
      isOfficialSource,

    needs_official_source_search:
      needsOfficialSourceSearch,

    validation_reason:
      cleanText(
        parsed.validation_reason
      ),

    /*
     * 공고 기본정보
     */
    title:
      cleanText(parsed.title) ||
      sourceTitle,

    organization:
      cleanText(
        parsed.organization
      ),

    target:
      cleanText(
        parsed.target
      ),

    support_summary:
      cleanText(
        parsed.support_summary
      ),

    region:
      cleanText(
        parsed.region
      ),

    /*
     * 모집 일정
     */
    start_date:
      startDate,

    start_time:
      startTime,

    start_at:
      startAt,

    deadline:
      deadline,

    deadline_time:
      deadlineTime,

    deadline_at:
      deadlineAt,

    start_original_text:
      cleanText(
        parsed.start_original_text
      ),

    deadline_original_text:
      cleanText(
        parsed.deadline_original_text
      ),

    is_rolling_recruitment:
      normalizeBoolean(
        parsed.is_rolling_recruitment,
        false
      ),

    schedule_needs_review:
      normalizeBoolean(
        parsed.schedule_needs_review,
        false
      ),

    /*
     * 신청방법
     */
    application_method:
      cleanText(
        parsed.application_method
      ),

    application_url:
      cleanText(
        parsed.application_url
      ),

    /*
     * 지원유형
     */
    primary_category:
      primaryCategory,

    support_categories:
      supportCategories,

    other_category_description:
      otherCategoryDescription,

    category_evidence:
      categoryEvidence,

    category_confidence:
      categoryConfidence,

    category_parse_success:
      categoryParseSuccess,

    category_needs_review:
      categoryNeedsReview,

    /*
     * DeepSeek 실행정보
     */
    deepseek_model:
      response?.model ?? null,

    deepseek_usage:
      response?.usage ?? null,

    deepseek_raw_content:
      rawContent
  }
};

const items = $input.all();
const seen = new Set();
const results = [];

for (const item of items) {
  const url = String(
    item.json.verification_url ||
    item.json.url ||
    ''
  ).trim();

  if (!url || seen.has(url)) {
    continue;
  }

  seen.add(url);
  results.push(item);
}

return results;

const dateFields = [
  'published_at',
  'start_date',
  'deadline',
  'start_at',
  'deadline_at'
];

return $input.all().map(item => {
  const data = { ...item.json };

  for (const field of dateFields) {
    const value = data[field];

    if (
      value === undefined ||
      value === null ||
      value === '' ||
      value === 'null' ||
      (typeof value === 'string' && value.trim() === '')
    ) {
      data[field] = null;
    }
  }

  return { json: data };
});

function emptyToNull(value) {
  if (value === undefined || value === null) return null;

  if (
    typeof value === 'string' &&
    value.trim() === ''
  ) {
    return null;
  }

  if (
    typeof value === 'string' &&
    value.trim().toLowerCase() === 'null'
  ) {
    return null;
  }

  return value;
}

function hasValue(value) {
  return !(
    value === undefined ||
    value === null ||
    String(value).trim() === '' ||
    String(value).trim().toLowerCase() === 'null'
  );
}

function makeDateTime(date, time, existingAt) {
  if (hasValue(existingAt)) {
    return existingAt;
  }

  if (!hasValue(date) || !hasValue(time)) {
    return null;
  }

  const dateText = String(date).trim();
  const timeText = String(time).trim();

  const normalizedTime =
    /^\d{2}:\d{2}$/.test(timeText)
      ? `${timeText}:00`
      : timeText;

  return `${dateText}T${normalizedTime}+09:00`;
}

/*
 * 문자열 "true", "false"가 들어와도
 * 실제 Boolean으로 변환한다.
 */
function toBoolean(value, fallback = false) {
  if (value === true) return true;
  if (value === false) return false;

  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();

    if (normalized === 'true') return true;
    if (normalized === 'false') return false;
  }

  if (value === 1) return true;
  if (value === 0) return false;

  return fallback;
}

return $input.all().map(item => {
  const j = item.json;

  const startAt = makeDateTime(
    j.start_date,
    j.start_time,
    j.start_at
  );

  const deadlineAt = makeDateTime(
    j.deadline,
    j.deadline_time,
    j.deadline_at
  );

  /*
   * Tavily 수정일 추출 Code에서 만든 값이다.
   *
   * 수정일이 발견되지 않았다면 null이 들어간다.
   */
  const sourceModifiedAt =
    emptyToNull(j.source_modified_at);

  const sourceModifiedDate =
    emptyToNull(j.source_modified_date);

  const sourceModifiedTime =
    emptyToNull(j.source_modified_time);

  const sourceModifiedOriginalText =
    emptyToNull(j.source_modified_original_text);

  const sourceModifiedConfidence =
    emptyToNull(j.source_modified_confidence);

  const sourceModifiedLabel =
    emptyToNull(j.source_modified_label);

  return {
    json: {
      /*
       * 출처 및 공고 식별정보
       */
      source: emptyToNull(j.source),
      notice_id: emptyToNull(j.notice_id),

      /*
       * 공고 기본정보
       */
      title: emptyToNull(j.title),
      organization: emptyToNull(j.organization),

      /*
       * 게시일 및 원본 수정일
       */
      published_at: emptyToNull(j.published_at),

      source_modified_at: sourceModifiedAt,
      source_modified_date: sourceModifiedDate,
      source_modified_time: sourceModifiedTime,

      source_modified_has_time:
        sourceModifiedAt !== null &&
        toBoolean(
          j.source_modified_has_time,
          sourceModifiedTime !== null
        ),

      source_modified_original_text:
        sourceModifiedOriginalText,

      source_modified_confidence:
        sourceModifiedConfidence,

      source_modified_label:
        sourceModifiedLabel,

      /*
       * 접수기간
       */
      start_date: emptyToNull(j.start_date),
      deadline: emptyToNull(j.deadline),

      start_at: emptyToNull(startAt),
      deadline_at: emptyToNull(deadlineAt),

      start_has_time:
        hasValue(j.start_time) ||
        hasValue(j.start_at),

      deadline_has_time:
        hasValue(j.deadline_time) ||
        hasValue(j.deadline_at),

      /*
       * 모집 및 지원정보
       */
      target: emptyToNull(j.target),
      excluded_target: emptyToNull(j.excluded_target),
      region: emptyToNull(j.region),
      field: emptyToNull(j.field),

      /*
       * 신청 및 링크정보
       */
      url: emptyToNull(j.url),
      application_method:
        emptyToNull(j.application_method),

      application_url:
        emptyToNull(j.application_url),

      /*
       * 원문
       *
       * 수정일 및 향후 내용변경을 판정할 때 필요하므로
       * 공통필드 변환에서 제거하면 안 된다.
       */
      raw_content: emptyToNull(
        j.raw_content ??
        j.results?.[0]?.raw_content ??
        j.content ??
        null
      ),

      /*
       * 원래 날짜 표현
       */
      start_raw: emptyToNull(j.start_raw),
      deadline_raw: emptyToNull(j.deadline_raw),

      /*
       * 시간대
       */
      timezone:
        emptyToNull(j.timezone) ||
        'Asia/Seoul'
    }
  };
});

function normalize(value) {
  if (value === undefined || value === null) {
    return '';
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (typeof value === 'object') {
    const sorted = {};

    for (const key of Object.keys(value).sort()) {
      sorted[key] = normalize(value[key]);
    }

    return sorted;
  }

  if (typeof value === 'string') {
    return value
      .normalize('NFKC')
      .replace(/\r\n/g, '\n')
      .replace(/\s+/g, ' ')
      .trim();
  }

  return value;
}

function fnv1a64(text) {
  let hash = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;

  for (let i = 0; i < text.length; i++) {
    hash ^= BigInt(text.charCodeAt(i));
    hash = BigInt.asUintN(64, hash * prime);
  }

  return hash.toString(16).padStart(16, '0');
}

const trackedFields = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'deadline',
  'start_at',
  'deadline_at',
  'application_method',
  'application_url',
  'url',
  'raw_content'
];

return $input.all().map(item => {
  const data = { ...item.json };
  const contentSnapshot = {};

  for (const field of trackedFields) {
    contentSnapshot[field] = normalize(data[field]);
  }

  const serialized = JSON.stringify(contentSnapshot);

  data.content_hash = fnv1a64(serialized);

  return {
    json: data
  };
});

return $input.all().map((item) => {
  const row = item.json;

  const exists = Boolean(
    row &&
    row.notice_id &&
    row.source_key
  );

  return {
    json: {
      existing_source_record: exists
        ? row
        : null
    }
  };
});

// 기존 content_hash 생성 노드와 동일한 정규화 규칙
function normalize(value) {
  if (value === undefined || value === null) {
    return '';
  }

  if (Array.isArray(value)) {
    return value.map(normalize);
  }

  if (typeof value === 'object') {
    const sorted = {};

    for (const key of Object.keys(value).sort()) {
      sorted[key] = normalize(value[key]);
    }

    return sorted;
  }

  if (typeof value === 'string') {
    return value
      .normalize('NFKC')
      .replace(/\r\n/g, '\n')
      .replace(/\s+/g, ' ')
      .trim();
  }

  return value;
}

function readHash(value) {
  if (value === undefined || value === null) {
    return null;
  }

  if (typeof value !== 'string') {
    throw new Error(
      'content_hash는 문자열이어야 합니다.'
    );
  }

  const text = value.trim();

  if (
    text === '' ||
    text.toLowerCase() === 'null' ||
    text.toLowerCase() === 'undefined'
  ) {
    return null;
  }

  return text;
}

// 기존 content_hash 생성 노드와 동일한 비교 필드
const trackedFields = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'deadline',
  'start_at',
  'deadline_at',
  'application_method',
  'application_url',
  'url',
  'raw_content',
];

function serializeContent(record) {
  const snapshot = {};

  for (const field of trackedFields) {
    snapshot[field] = normalize(record[field]);
  }

  return JSON.stringify(snapshot);
}

return $input.all().map((item, index) => {
  const current = item.json;

  const existingSource =
    current.existing_source_record &&
    current.existing_source_record.notice_id
      ? current.existing_source_record
      : null;

  const newHash = readHash(current.content_hash);
  const oldHash = readHash(
    existingSource?.content_hash
  );

  // 새 해시가 없으면 변경 여부를 잘못 판단할 수 있으므로 중단
  if (!newHash) {
    throw new Error(
      `아이템 ${index + 1}: 신규 content_hash가 없습니다. ` +
      '앞의 content_hash 생성 노드 출력을 확인하세요.'
    );
  }

  let comparison_status;

  if (!existingSource) {
    // 같은 source_key의 기존 출처 기록이 없음
    comparison_status = 'source_not_found';
  } else if (!oldHash) {
    // 기존 해시가 없으면 실제 저장 내용과 신규 내용을 비교
    const oldContent = serializeContent(existingSource);
    const newContent = serializeContent(current);

    if (oldContent === newContent) {
      // 내용은 같고 기존 해시만 없음 → 2번
      comparison_status = 'content_hash_required';
    } else {
      // 기존 해시가 없더라도 내용이 다르면 → 4번
      comparison_status = 'changed';
    }
  } else if (oldHash === newHash) {
    // 기존 해시와 신규 해시가 같음 → 3번
    comparison_status = 'unchanged';
  } else {
    // 기존 해시와 신규 해시가 다름 → 4번
    comparison_status = 'changed';
  }

  return {
    json: {
      ...current,

      comparison_status,

      is_existing_source: Boolean(existingSource),

      // 연결된 notices 행의 UUID
      existing_notice_id:
        existingSource?.notice_id || null,

      // 기존 notice_sources 행 자체의 UUID
      existing_source_id:
        existingSource?.id || null,

      old_content_hash: oldHash,
      new_content_hash: newHash,
    },

    pairedItem: {
      item: index,
    },
  };
});

