return $input.all().map((item) => {
  let content = item.json.choices?.[0]?.message?.content;

  if (!content) {
    throw new Error(
      'DeepSeek 응답에서 choices[0].message.content를 찾을 수 없습니다.'
    );
  }

  /*
   * 혹시 코드블록으로 감싸서 반환했을 경우 제거한다.
   */
  content = String(content)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let decision;

  try {
    decision = JSON.parse(content);
  } catch (error) {
    throw new Error(
      `DeepSeek 응답을 JSON으로 변환하지 못했습니다: ${content}`
    );
  }

  if (!Array.isArray(decision.field_decisions)) {
    decision.field_decisions = [];
  }

  if (!Array.isArray(decision.changed_fields)) {
    decision.changed_fields = [];
  }

  if (!Array.isArray(decision.kept_fields)) {
    decision.kept_fields = [];
  }

  if (!Array.isArray(decision.review_fields)) {
    decision.review_fields = [];
  }

  return {
    json: {
      deepseek_decision: decision
    }
  };
});

const CANONICAL_FIELDS = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
];

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  );
}

function normalize(value) {
  if (value === null || value === undefined) return '';

  if (Array.isArray(value)) {
    return value
      .map(v => String(v).normalize('NFKC').trim())
      .filter(Boolean)
      .sort()
      .join('|');
  }

  return String(value)
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

function fnv1a64(text) {
  let hash = 0xcbf29ce484222325n;
  const prime = 0x100000001b3n;

  for (let i = 0; i < text.length; i++) {
    hash ^= BigInt(text.charCodeAt(i));
    hash = BigInt.asUintN(64, hash * prime);
  }

  return hash.toString(16).padStart(16, '0');
}

return $input.all().map((item) => {
  const data = item.json;

  const decision = data.deepseek_decision || {};

  const fieldDecisions = Array.isArray(decision.field_decisions)
    ? decision.field_decisions
    : [];

  /*
   * dedupe_record:
   * notices에 저장된 기존 대표공고
   *
   * canonical_record:
   * 앞의 역할분기에서 빈 필드 보완 및 source_keys 병합까지
   * 반영해 놓은 후보 통합공고
   */
  const existingRecord = data.dedupe_record || {};

  const finalRecord = {
    ...existingRecord,
    ...(data.canonical_record || {}),
  };

  const appliedFields = [];
  const keptFields = [];
  const reviewFields = [];
  const rejectedUpdates = [];

  for (const fieldDecision of fieldDecisions) {
    const field = fieldDecision.field;

    /*
     * notices 통합필드가 아니면 적용하지 않는다.
     */
    if (!CANONICAL_FIELDS.includes(field)) {
      rejectedUpdates.push({
        field: field ?? null,
        reason: '허용된 notices 통합필드가 아님',
      });

      continue;
    }

    /*
     * 기존값 유지 판정
     */
    if (fieldDecision.action === 'keep_existing') {
      keptFields.push({
        field,
        value: existingRecord[field] ?? null,
        reason: fieldDecision.reason ?? null,
        confidence: fieldDecision.confidence ?? null,
      });

      continue;
    }

    /*
     * 추가검토 판정은 기존값을 유지한다.
     */
    if (fieldDecision.action === 'review') {
      finalRecord[field] = existingRecord[field] ?? null;

      reviewFields.push({
        field,
        existing_value: fieldDecision.existing_value ?? null,
        incoming_value: fieldDecision.incoming_value ?? null,
        reason: fieldDecision.reason ?? null,
        evidence: fieldDecision.evidence ?? null,
        freshness_basis: fieldDecision.freshness_basis ?? null,
        confidence: fieldDecision.confidence ?? null,
      });

      continue;
    }

    /*
     * update가 아니면 적용하지 않는다.
     */
    if (fieldDecision.action !== 'update') {
      rejectedUpdates.push({
        field,
        reason: `알 수 없는 action: ${fieldDecision.action}`,
      });

      continue;
    }

    /*
     * high가 아니면 review로 처리하고 기존값을 유지한다.
     */
    if (fieldDecision.confidence !== 'high') {
      finalRecord[field] = existingRecord[field] ?? null;

      reviewFields.push({
        field,
        existing_value: fieldDecision.existing_value ?? null,
        incoming_value: fieldDecision.incoming_value ?? null,
        reason: 'update 판정이지만 confidence가 high가 아님',
        evidence: fieldDecision.evidence ?? null,
        freshness_basis: fieldDecision.freshness_basis ?? null,
        confidence: fieldDecision.confidence ?? null,
      });

      continue;
    }

    /*
     * evidence가 없으면 자동 적용하지 않는다.
     */
    if (isEmpty(fieldDecision.evidence)) {
      finalRecord[field] = existingRecord[field] ?? null;

      reviewFields.push({
        field,
        existing_value: fieldDecision.existing_value ?? null,
        incoming_value: fieldDecision.incoming_value ?? null,
        reason: 'update 판정이지만 evidence가 없음',
        evidence: null,
        freshness_basis: fieldDecision.freshness_basis ?? null,
        confidence: fieldDecision.confidence ?? null,
      });

      continue;
    }

    /*
     * 어떤 값이 최신인지 판단한 근거가 없으면 적용하지 않는다.
     */
    if (isEmpty(fieldDecision.freshness_basis)) {
      finalRecord[field] = existingRecord[field] ?? null;

      reviewFields.push({
        field,
        existing_value: fieldDecision.existing_value ?? null,
        incoming_value: fieldDecision.incoming_value ?? null,
        reason: 'update 판정이지만 freshness_basis가 없음',
        evidence: fieldDecision.evidence ?? null,
        freshness_basis: null,
        confidence: fieldDecision.confidence ?? null,
      });

      continue;
    }

    const selectedValue =
      fieldDecision.selected_value ?? null;

    /*
     * 최종 선택값이 없으면 적용할 수 없다.
     */
    if (isEmpty(selectedValue)) {
      finalRecord[field] = existingRecord[field] ?? null;

      reviewFields.push({
        field,
        existing_value: fieldDecision.existing_value ?? null,
        incoming_value: fieldDecision.incoming_value ?? null,
        reason: 'update 판정이지만 selected_value가 없음',
        evidence: fieldDecision.evidence ?? null,
        freshness_basis: fieldDecision.freshness_basis ?? null,
        confidence: fieldDecision.confidence ?? null,
      });

      continue;
    }

    const oldValue = existingRecord[field] ?? null;

    /*
     * 정규화 후 기존값과 같으면 실제 변경으로 처리하지 않는다.
     */
    if (normalize(oldValue) === normalize(selectedValue)) {
      keptFields.push({
        field,
        value: oldValue,
        reason: '정규화 후 기존값과 동일함',
        confidence: fieldDecision.confidence,
      });

      continue;
    }

    /*
     * 모든 안전조건을 통과한 필드만 최종값에 반영한다.
     */
    finalRecord[field] = selectedValue;

    appliedFields.push({
      field,
      old_value: oldValue,
      new_value: selectedValue,
      reason: fieldDecision.reason ?? null,
      evidence: fieldDecision.evidence,
      freshness_basis: fieldDecision.freshness_basis,
      confidence: fieldDecision.confidence,
    });
  }

  /*
   * 앞의 역할분기에서 보완된 빈 필드가 있는지 확인한다.
   */
  const enrichedFields = Array.isArray(data.enriched_fields)
    ? data.enriched_fields
    : [];

  const hasDeepSeekChanges = appliedFields.length > 0;
  const hasEnrichedFields = enrichedFields.length > 0;

  const hasMeaningfulUpdate =
    hasDeepSeekChanges || hasEnrichedFields;

  /*
   * 새로운 출처키는 필드 변경 여부와 관계없이 notices에 추가한다.
   */
  if (Array.isArray(data.merged_source_keys)) {
    finalRecord.source_keys = [
      ...new Set(data.merged_source_keys.filter(Boolean))
    ];
  }

  /*
   * 공고를 다시 확인한 시각
   */
  finalRecord.last_seen_at = new Date().toISOString();

  /*
   * 실제 통합필드 변경 또는 빈 필드 보완이 있을 때만
   * canonical content_hash와 updated_at을 갱신한다.
   */
  if (hasMeaningfulUpdate) {
    const canonicalHashPayload = {};

    for (const field of CANONICAL_FIELDS) {
      canonicalHashPayload[field] = normalize(
        finalRecord[field] ?? null
      );
    }

    finalRecord.content_hash = fnv1a64(
      JSON.stringify(canonicalHashPayload)
    );

    finalRecord.updated_at = new Date().toISOString();
  } else {
    /*
     * 단순 출처 추가 또는 review인 경우 기존 값을 유지한다.
     */
    finalRecord.content_hash =
      existingRecord.content_hash ?? finalRecord.content_hash ?? null;

    finalRecord.updated_at =
      existingRecord.updated_at ?? finalRecord.updated_at ?? null;
  }

  /*
   * Supabase notices Update에 전달할 필드만 추린다.
   */
  const noticesUpdateRecord = {};

  const allowedNoticeFields = [
    'id',
    'canonical_key',
    'source_key',
    'source_keys',
    'dedupe_key',
    ...CANONICAL_FIELDS,
    'content_hash',
    'first_seen_at',
    'last_seen_at',
    'updated_at',
  ];

  for (const field of allowedNoticeFields) {
    if (finalRecord[field] !== undefined) {
      noticesUpdateRecord[field] = finalRecord[field];
    }
  }

  return {
    json: {
      ...data,

      applied_fields: appliedFields,
      kept_fields_result: keptFields,
      review_fields_result: reviewFields,
      rejected_updates: rejectedUpdates,

      has_meaningful_update: hasMeaningfulUpdate,
      has_review_fields: reviewFields.length > 0,

      notices_update_record: noticesUpdateRecord,
    },
  };
});

/*
 * Tavily 원문에서 명시적으로 표시된 수정일을 추출한다.
 *
 * 추출 대상 예:
 * - 수정일
 * - 수정일자
 * - 수정일시
 * - 최종수정일
 * - 최종 수정 일시
 * - 최근 수정일
 * - 마지막 수정일
 * - 변경일
 * - 변경일자
 * - 변경일시
 * - 최종변경일
 * - 갱신일
 * - 최종갱신일
 * - 업데이트일
 * - 최종 업데이트 일자
 * - 정정일
 *
 * 주의:
 * - 단순 '등록일'은 수정일로 취급하지 않는다.
 * - '[수정공고]'의 등록일도 source_modified_at으로 자동 변환하지 않는다.
 */

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  );
}

function getFirstNonEmpty(...values) {
  for (const value of values) {
    if (!isEmpty(value)) {
      return String(value);
    }
  }

  return '';
}

/*
 * HTML 태그와 자주 사용되는 엔티티를 정리한다.
 */
function cleanText(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\r/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .normalize('NFKC')
    .trim();
}

function pad2(value) {
  return String(value).padStart(2, '0');
}

/*
 * 실제 존재하는 날짜인지 확인한다.
 * 예: 2026-02-31은 허용하지 않는다.
 */
function isValidDate(year, month, day) {
  const date = new Date(Date.UTC(year, month - 1, day));

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/*
 * 오전·오후가 포함된 시간을 24시간제로 바꾼다.
 */
function normalizeTime(ampm, hourValue, minuteValue) {
  if (hourValue === undefined || hourValue === null) {
    return null;
  }

  let hour = Number(hourValue);
  const minute = Number(minuteValue || 0);

  if (
    Number.isNaN(hour) ||
    Number.isNaN(minute) ||
    minute < 0 ||
    minute > 59
  ) {
    return null;
  }

  const period = String(ampm || '').trim();

  if (period === '오후' && hour < 12) {
    hour += 12;
  }

  if (period === '오전' && hour === 12) {
    hour = 0;
  }

  if (hour < 0 || hour > 23) {
    return null;
  }

  return {
    hour,
    minute,
    formatted: `${pad2(hour)}:${pad2(minute)}`,
  };
}

/*
 * 수정일 라벨의 우선순위다.
 * 구체적인 라벨을 먼저 검사한다.
 */
const labelPatterns = [
  {
    type: 'final_modified',
    confidence: 'high',
    pattern:
      '(?:최종|마지막|최근)\\s*(?:수정|변경|갱신|업데이트)\\s*(?:일시|일자|날짜|일)?',
  },
  {
    type: 'modified',
    confidence: 'high',
    pattern:
      '수정\\s*(?:등록\\s*)?(?:일시|일자|날짜|일)',
  },
  {
    type: 'corrected',
    confidence: 'high',
    pattern:
      '정정\\s*(?:등록\\s*)?(?:일시|일자|날짜|일)',
  },
  {
    type: 'changed',
    confidence: 'medium',
    pattern:
      '변경\\s*(?:등록\\s*)?(?:일시|일자|날짜|일)',
  },
  {
    type: 'updated',
    confidence: 'medium',
    pattern:
      '(?:업데이트|갱신)\\s*(?:일시|일자|날짜|일)',
  },
];

/*
 * 지원하는 날짜 형식:
 *
 * 2026-09-05
 * 2026.09.05
 * 2026/09/05
 * 2026년 9월 5일
 * 20260905
 * 26.09.05
 *
 * 지원하는 시간 형식:
 *
 * 14:30
 * 14시 30분
 * 오후 2시 30분
 * 오전 9시
 */
const datePattern =
  '(?:' +
    '(?<year4>20\\d{2})\\s*(?:년|[.\\-/])\\s*' +
    '(?<month4>0?[1-9]|1[0-2])\\s*(?:월|[.\\-/])\\s*' +
    '(?<day4>0?[1-9]|[12]\\d|3[01])\\s*일?' +
  '|' +
    '(?<compactYear>20\\d{2})' +
    '(?<compactMonth>0[1-9]|1[0-2])' +
    '(?<compactDay>0[1-9]|[12]\\d|3[01])' +
  '|' +
    '(?<year2>\\d{2})\\s*[.\\-/]\\s*' +
    '(?<month2>0?[1-9]|1[0-2])\\s*[.\\-/]\\s*' +
    '(?<day2>0?[1-9]|[12]\\d|3[01])' +
  ')';

const timePattern =
  '(?:' +
    '\\s*(?:\\([^)]*\\)\\s*)?' +
    '(?<ampm>오전|오후)?\\s*' +
    '(?<hour>[01]?\\d|2[0-3])' +
    '(?:' +
      '\\s*:\\s*(?<minuteColon>[0-5]\\d)' +
      '|' +
      '\\s*시(?:\\s*(?<minuteKorean>[0-5]?\\d)\\s*분?)?' +
    ')' +
  ')?';

function extractModifiedDate(text) {
  if (!text) return null;

  const matches = [];

  for (let priority = 0; priority < labelPatterns.length; priority++) {
    const label = labelPatterns[priority];

    /*
     * 라벨과 날짜 사이에는 콜론, 괄호, 공백, 하이픈 등만 허용한다.
     * 일반 문장이 길게 들어가면 잘못된 날짜를 잡을 수 있기 때문이다.
     */
    const expression = new RegExp(
      `(?<label>${label.pattern})` +
      '\\s*(?:[:：]|-|–|—|=|\\(|\\)|\\[|\\])*\\s*' +
      `(?<date>${datePattern})` +
      timePattern,
      'giu'
    );

    for (const match of text.matchAll(expression)) {
      const groups = match.groups || {};

      let year;
      let month;
      let day;

      if (groups.year4) {
        year = Number(groups.year4);
        month = Number(groups.month4);
        day = Number(groups.day4);
      } else if (groups.compactYear) {
        year = Number(groups.compactYear);
        month = Number(groups.compactMonth);
        day = Number(groups.compactDay);
      } else if (groups.year2) {
        year = 2000 + Number(groups.year2);
        month = Number(groups.month2);
        day = Number(groups.day2);
      } else {
        continue;
      }

      if (!isValidDate(year, month, day)) {
        continue;
      }

      const minute =
        groups.minuteColon ??
        groups.minuteKorean ??
        null;

      const time = normalizeTime(
        groups.ampm,
        groups.hour,
        minute
      );

      const normalizedDate =
        `${year}-${pad2(month)}-${pad2(day)}`;

      /*
       * 시간이 명시된 경우에만 완전한 KST 시각을 생성한다.
       * 시간이 없으면 날짜 문자열만 저장한다.
       */
      const normalizedValue = time
        ? `${normalizedDate}T${time.formatted}:00+09:00`
        : normalizedDate;

      matches.push({
        priority,
        label_type: label.type,
        label: groups.label || null,
        value: normalizedValue,
        date: normalizedDate,
        time: time?.formatted || null,
        has_time: Boolean(time),
        original_text: match[0].trim(),
        confidence: label.confidence,
        position: match.index ?? 0,
      });
    }
  }

  if (matches.length === 0) {
    return null;
  }

  /*
   * 1. 명확한 라벨 우선
   * 2. 같은 우선순위면 원문 뒤쪽의 수정일 우선
   *
   * 변경 이력이 여러 줄로 나열된 경우 일반적으로 뒤쪽 값이
   * 최신일 가능성이 높지만, 이것만으로 실제 최신성을 확정하지 않는다.
   */
  matches.sort((a, b) => {
    if (a.priority !== b.priority) {
      return a.priority - b.priority;
    }

    return b.position - a.position;
  });

  return {
    selected: matches[0],
    all_matches: matches,
  };
}

return $input.all().map((item) => {
  const data = item.json;

  /*
   * Tavily 경로에서 원문이 저장될 수 있는 위치를 차례대로 확인한다.
   */
  const rawContent = getFirstNonEmpty(
    data.raw_content,
    data.results?.[0]?.raw_content,
    data.content,
    data.description
  );

  const cleanedContent = cleanText(rawContent);
  const extraction = extractModifiedDate(cleanedContent);

  /*
   * 앞 노드에서 이미 신뢰할 수 있는 수정일을 만들었다면
   * 기존값을 우선 유지한다.
   */
  const existingModifiedAt =
    !isEmpty(data.source_modified_at)
      ? data.source_modified_at
      : null;

  const selected = extraction?.selected || null;

  return {
    json: {
      ...data,

      source_modified_at:
        existingModifiedAt ||
        selected?.value ||
        null,

      source_modified_date:
        selected?.date ||
        null,

      source_modified_time:
        selected?.time ||
        null,

      source_modified_has_time:
        selected?.has_time ??
        false,

      source_modified_label:
        selected?.label ||
        null,

      source_modified_original_text:
        selected?.original_text ||
        null,

      source_modified_confidence:
        existingModifiedAt
          ? 'existing'
          : selected?.confidence || null,

      /*
       * 여러 수정일이 발견됐을 때 확인할 수 있도록 남긴다.
       * 이 배열은 DB 저장용이 아니라 검증용이다.
       */
      source_modified_candidates:
        extraction?.all_matches || [],
    },
  };
});

return $input.all().map((item) => {
  const record = item.json.notices_update_record;

  if (!record?.id) {
    throw new Error(
      'notices_update_record.id가 없습니다. DeepSeek 판정 적용 노드 출력을 확인하세요.'
    );
  }

  return {
    json: record,
  };
});

function emptyToNull(value) {
  if (value === undefined || value === null) {
    return null;
  }

  if (typeof value === 'string') {
    const text = value.trim();

    if (text === '' || text.toLowerCase() === 'null') {
      return null;
    }

    return text;
  }

  return value;
}

function toArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);

      if (Array.isArray(parsed)) {
        return parsed;
      }
    } catch {
      return [value.trim()];
    }
  }

  return [];
}

function isUuid(value) {
  return typeof value === 'string' &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      value
    );
}

function createUuid() {
  if (
    typeof globalThis.crypto !== 'undefined' &&
    typeof globalThis.crypto.randomUUID === 'function'
  ) {
    return globalThis.crypto.randomUUID();
  }

  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(
    /[xy]/g,
    (character) => {
      const random = Math.floor(Math.random() * 16);
      const value = character === 'x'
        ? random
        : (random & 0x3) | 0x8;

      return value.toString(16);
    }
  );
}

return $input.all().map((item) => {
  const j = item.json;
  const now = new Date().toISOString();

  /*
   * 이전 처리 단계에서 이미 UUID가 만들어졌다면 그것을 사용하고,
   * 없다면 신규 UUID를 만든다.
   */
  const newNoticeId =
    isUuid(j.canonical_key)
      ? j.canonical_key
      : isUuid(j.id)
        ? j.id
        : createUuid();

  const sourceKeys = [
    ...toArray(j.source_keys),
    emptyToNull(j.source_key),
  ].filter(Boolean);

  const uniqueSourceKeys = [...new Set(sourceKeys)];

  /*
   * 아래에 반환하는 값만 Supabase notices에 전달된다.
   * existing_notice_id 등의 작업용 값은 의도적으로 제외한다.
   */
  return {
    json: {
      id: newNoticeId,
      canonical_key: newNoticeId,

      source: emptyToNull(j.source),
      source_key: emptyToNull(j.source_key),
      source_keys: uniqueSourceKeys,
      dedupe_key: emptyToNull(j.dedupe_key),

      notice_id: emptyToNull(j.notice_id),
      title: emptyToNull(j.title),
      organization: emptyToNull(j.organization),

      published_at: emptyToNull(j.published_at),
      start_date: emptyToNull(j.start_date),
      deadline: emptyToNull(j.deadline),

      target: emptyToNull(j.target),
      excluded_target: emptyToNull(j.excluded_target),
      region: emptyToNull(j.region),
      field: emptyToNull(j.field),

      url: emptyToNull(j.url),
      application_method: emptyToNull(j.application_method),
      application_url: emptyToNull(j.application_url),

      start_at: emptyToNull(j.start_at),
      deadline_at: emptyToNull(j.deadline_at),

      start_has_time: Boolean(j.start_has_time),
      deadline_has_time: Boolean(j.deadline_has_time),

      start_raw: emptyToNull(j.start_raw),
      deadline_raw: emptyToNull(j.deadline_raw),
      timezone: emptyToNull(j.timezone) || 'Asia/Seoul',

      raw_content: emptyToNull(j.raw_content),
      content_hash: emptyToNull(j.content_hash),

      first_seen_at: emptyToNull(j.first_seen_at) || now,
      last_seen_at: emptyToNull(j.last_seen_at) || now,
      updated_at: emptyToNull(j.updated_at) || now,
    },
  };
});

function cleanText(value) {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value)
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

/*
 * 제목 비교용 키 생성
 *
 * 공백, 괄호, 특수문자를 제거하고
 * 한글, 영문, 숫자만 유지한다.
 */
function makeTitleKey(value) {
  return cleanText(value)
    .toLowerCase()
    .replace(/[^0-9a-z가-힣]/g, '');
}

/*
 * 추가모집·재공고·별도 모집 회차 표현
 *
 * '기간 연장', '접수 연장'은 포함하지 않는다.
 * 마감일만 변경된 기존공고일 수 있기 때문이다.
 */
const additionalPattern =
  /추가\s*모집|추가\s*공고|재\s*모집|재\s*공고|후속\s*모집|(?:제\s*)?\d+\s*차\s*(?:모집|공고)/i;

/*
 * 수정·정정·변경공고 판정
 *
 * 다음 형태를 판정한다.
 *
 * [수정공고] 제목
 * 제목 (정정)
 * 수정공고: 제목
 * 제목 수정 공고 안내
 * 제목 변경공고
 * 제목 - 변경 - 안내
 */
const correctionPattern =
  /수정\s*공고|정정\s*공고|변경\s*공고|(?:^|[\[\(\{【<\s\-_:：])(?:수정|정정|변경)(?=$|[\]\)\}】>\s\-_:：])/i;

/*
 * 수정·정정·변경 표현을 정리한다.
 *
 * 규칙 1:
 * [수정공고], (정정), 【변경공고】처럼
 * 별도 표식이면 표식 전체를 제거한다.
 *
 * 규칙 2:
 * 수정공고:, 정정:, 변경공고:처럼
 * 제목 앞의 메타표시이면 전체를 제거한다.
 *
 * 규칙 3:
 * 제목 내용 중에 들어간 수정·정정·변경은
 * 해당 단어만 제거하고 '공고'는 남긴다.
 */
function removeCorrectionMarkers(value) {
  let title = cleanText(value);

  /*
   * 1. 괄호로 구분된 별도 메타표시 전체 제거
   *
   * [수정공고]
   * (정정)
   * 【변경 공고】
   */
  title = title.replace(
    /[\[\(\{【<]\s*(?:수정|정정|변경)\s*(?:공고)?\s*[\]\)\}】>]/gi,
    ' '
  );

  /*
   * 2. 제목 앞의 콜론 메타표시 전체 제거
   *
   * 수정공고: 제목
   * 정정 : 제목
   * 변경 공고：제목
   */
  title = title.replace(
    /^\s*(?:수정|정정|변경)\s*(?:공고)?\s*[:：]\s*/i,
    ''
  );

  /*
   * 3. 제목 뒤의 콜론 메타표시 전체 제거
   *
   * 제목 : 수정공고
   * 제목: 정정
   */
  title = title.replace(
    /\s*[:：]\s*(?:수정|정정|변경)\s*(?:공고)?\s*$/i,
    ''
  );

  /*
   * 4. 제목 앞에서 별도 표식처럼 사용된 표현 제거
   *
   * 수정공고 - 제목
   * 정정_제목
   * 변경 공고 / 제목
   *
   * 이 경우는 제목 내용이 아니라 메타표시이므로
   * '공고'까지 제거한다.
   */
  title = title.replace(
    /^\s*(?:수정|정정|변경)\s*(?:공고)?\s*[-_:/：]\s*/i,
    ''
  );

  /*
   * 5. 제목 내용 중 '수정공고·정정공고·변경공고'는
   * 수정·정정·변경 단어만 제거하고 '공고'는 유지한다.
   *
   * 제목 수정 공고 안내
   * → 제목 공고 안내
   *
   * 제목 변경공고
   * → 제목 공고
   */
  title = title.replace(
    /(?:수정|정정|변경)(?=\s*공고)/gi,
    ''
  );

  /*
   * 6. 제목 내용 중 독립적으로 사용된
   * 수정·정정·변경 단어만 제거한다.
   *
   * 제목 - 변경 - 안내
   * → 제목 - 안내
   */
  title = title.replace(
    /(^|[\s\-_:：/])(?:수정|정정|변경)(?=$|[\s\-_:：/])/gi,
    '$1'
  );

  /*
   * 7. 제거 후 남은 중복 구분기호와 공백 정리
   */
  title = title
    .replace(/\s*[-_:：/]\s*[-_:：/]\s*/g, ' ')
    .replace(/^\s*[-_:：/]\s*/g, '')
    .replace(/\s*[-_:：/]\s*$/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  return title;
}

