  ) {
    throw new Error(
      '충돌 필드가 없습니다. Switch2의 conflict 출력 연결을 확인하세요.'
    );
  }

  return {
    json: {
      // 기존 ID, source_record, 보완된 저장값 등을 유지
      ...current,

      // 다음 DeepSeek 노드에 전달할 판단 자료
      conflict_judgment_input: {
        notice_id: current.canonical_record.id,

        existing: context.existing,
        incoming: context.incoming,

        // 판단 대상은 실제 충돌한 필드만
        conflicting_fields: current.conflicting_fields,
      },
    },

    pairedItem: {
      item: index,
    },
  };
});

const COMPARISON_FIELDS = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
];

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  );
}

function normalizeText(value) {
  if (isEmpty(value)) return null;

  if (Array.isArray(value)) {
    return value
      .map(v => String(v).trim())
      .filter(Boolean);
  }

  return String(value)
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

function getFirstValue(...values) {
  for (const value of values) {
    if (!isEmpty(value)) return value;
  }

  return null;
}

function getFieldValue(record, field) {
  if (!record || typeof record !== 'object') return null;

  return record[field] ?? null;
}

/*
 * 날짜를 비교하기 위한 보조 함수다.
 * 날짜가 유효하지 않으면 null을 반환한다.
 */
function parseTimestamp(value) {
  if (isEmpty(value)) return null;

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) return null;

  return {
    original: value,
    iso: parsed.toISOString(),
    timestamp: parsed.getTime(),
  };
}

/*
 * 원문에서 특정 값 또는 변경 관련 표현 주변 문장을 추출한다.
 * DeepSeek에는 전체 원문도 전달하되, 중요한 부분을 별도로 보여준다.
 */
function extractEvidenceSnippets(rawContent, searchValues = []) {
  if (isEmpty(rawContent)) return [];

  const raw = String(rawContent)
    .replace(/\r/g, '\n')
    .replace(/\n{2,}/g, '\n')
    .trim();

  const normalizedRaw = raw
    .normalize('NFKC')
    .replace(/\s+/g, ' ');

  const keywords = [
    ...searchValues
      .filter(value => !isEmpty(value))
      .map(value => String(value).trim()),

    '변경',
    '수정',
    '정정',
    '연장',
    '접수기간',
    '신청기간',
    '마감일',
    '추가모집',
    '재공고',
    '모집기간',
    '신청방법',
    '모집대상',
  ];

  const snippets = [];

  for (const keyword of [...new Set(keywords)]) {
    const normalizedKeyword = keyword
      .normalize('NFKC')
      .replace(/\s+/g, ' ')
      .trim();

    if (!normalizedKeyword) continue;

    const index = normalizedRaw
      .toLowerCase()
      .indexOf(normalizedKeyword.toLowerCase());

    if (index === -1) continue;

    const start = Math.max(0, index - 180);
    const end = Math.min(
      normalizedRaw.length,
      index + normalizedKeyword.length + 220
    );

    const snippet = normalizedRaw
      .slice(start, end)
      .trim();

    if (snippet && !snippets.includes(snippet)) {
      snippets.push(snippet);
    }

    /*
     * 원문이 지나치게 길어지지 않도록 최대 12개만 추출한다.
     */
    if (snippets.length >= 12) break;
  }

  return snippets;
}

return $input.all().map((item) => {
  const data = item.json;

  /*
   * 기존 대표공고와 신규 출처 공고를 확보한다.
   */
  const existingRecord =
    data.deepseek_context?.existing ||
    data.dedupe_record ||
    {};

  const incomingRecord =
    data.deepseek_context?.incoming ||
    data.source_record ||
    {};

  const conflicts = Array.isArray(data.conflicting_fields)
    ? data.conflicting_fields
    : [];

  /*
   * conflicting_fields의 속성명이 조금 달라도 값을 찾을 수 있게 한다.
   */
  const conflictDetails = conflicts.map(conflict => {
    const field =
      conflict.field ||
      conflict.field_name ||
      conflict.name ||
      null;

    const existingValue = getFirstValue(
      conflict.existing_value,
      conflict.existing,
      field ? getFieldValue(existingRecord, field) : null
    );

    const incomingValue = getFirstValue(
      conflict.incoming_value,
      conflict.incoming,
      conflict.new_value,
      field ? getFieldValue(incomingRecord, field) : null
    );

    return {
      field,
      existing_value: existingValue,
      incoming_value: incomingValue,
      normalized_existing_value: normalizeText(existingValue),
      normalized_incoming_value: normalizeText(incomingValue),
      existing_is_empty: isEmpty(existingValue),
      incoming_is_empty: isEmpty(incomingValue),
    };
  });

  /*
   * 비교대상 통합필드를 한눈에 비교할 수 있는 객체로 만든다.
   */
  const fieldComparison = {};

  for (const field of COMPARISON_FIELDS) {
    const existingValue = getFieldValue(existingRecord, field);
    const incomingValue = getFieldValue(incomingRecord, field);

    fieldComparison[field] = {
      existing_value: existingValue,
      incoming_value: incomingValue,
      normalized_existing_value: normalizeText(existingValue),
      normalized_incoming_value: normalizeText(incomingValue),

      is_different:
        JSON.stringify(normalizeText(existingValue)) !==
        JSON.stringify(normalizeText(incomingValue)),
    };
  }

  const existingRawContent = getFirstValue(
    existingRecord.raw_content,
    existingRecord.content,
    data.deepseek_context?.existing_raw_content
  );

  const incomingRawContent = getFirstValue(
    incomingRecord.raw_content,
    incomingRecord.content,
    data.deepseek_context?.incoming_raw_content
  );

  /*
   * 원문에서 찾아볼 충돌값 목록을 만든다.
   */
  const existingSearchValues = conflictDetails
    .map(conflict => conflict.existing_value)
    .filter(value => !isEmpty(value));

  const incomingSearchValues = conflictDetails
    .map(conflict => conflict.incoming_value)
    .filter(value => !isEmpty(value));

  /*
   * 날짜 정보는 판단자료로만 제공한다.
   * DB updated_at이나 last_seen_at이 공고 원문의 수정일이라는
   * 의미는 아니므로 별도 구분한다.
   */
  const existingDates = {
    source_published_at: parseTimestamp(
      getFirstValue(
        existingRecord.published_at,
        existingRecord.notice_published_at
      )
    ),

    source_modified_at: parseTimestamp(
      getFirstValue(
        existingRecord.source_modified_at,
        existingRecord.modified_at
      )
    ),

    first_seen_at: parseTimestamp(existingRecord.first_seen_at),
    last_seen_at: parseTimestamp(existingRecord.last_seen_at),

    database_updated_at: parseTimestamp(existingRecord.updated_at),
  };

  const incomingDates = {
    source_published_at: parseTimestamp(
      getFirstValue(
        incomingRecord.published_at,
        incomingRecord.notice_published_at
      )
    ),

    source_modified_at: parseTimestamp(
      getFirstValue(
        incomingRecord.source_modified_at,
        incomingRecord.modified_at
      )
    ),

    first_seen_at: parseTimestamp(incomingRecord.first_seen_at),
    last_seen_at: parseTimestamp(incomingRecord.last_seen_at),

    collected_at: {
      original: new Date().toISOString(),
      iso: new Date().toISOString(),
      timestamp: Date.now(),
    },
  };

  const verificationContext = {
    comparison_purpose:
      '동일 공고의 서로 다른 출처에서 충돌한 통합필드 중 실제 최신값을 판단',

    cautions: [
      '신규로 수집되었다는 사실만으로 최신값이라고 판단하지 않는다.',
      'DB의 updated_at은 원본 공고 수정일이 아닐 수 있다.',
      'last_seen_at은 수집 시각이며 원본 공고 수정일이 아니다.',
      '명시적인 변경 문구가 없어도 공식 원문에 변경된 값이 명확할 수 있다.',
      '최신성 근거가 불충분하면 review로 판정한다.',
    ],

    conflict_fields: conflictDetails,
    field_comparison: fieldComparison,

    existing: {
      source: getFirstValue(
        existingRecord.source,
        existingRecord.source_name
      ),

      source_role: getFirstValue(
        existingRecord.source_role,
        existingRecord.is_official_source === true
          ? 'primary_official'
          : null
      ),

      source_key: existingRecord.source_key ?? null,

      url: getFirstValue(
        existingRecord.url,
        existingRecord.source_url
      ),

      dates: existingDates,

      fields: Object.fromEntries(
        COMPARISON_FIELDS.map(field => [
          field,
          getFieldValue(existingRecord, field),
        ])
      ),

      evidence_snippets: extractEvidenceSnippets(
        existingRawContent,
        existingSearchValues
      ),

      raw_content: existingRawContent,
    },

    incoming: {
      source: getFirstValue(
        incomingRecord.source,
        incomingRecord.source_name
      ),

      source_role: getFirstValue(
        incomingRecord.source_role,
        incomingRecord.is_official_source === true
          ? 'primary_official'
          : null
      ),

      source_key: incomingRecord.source_key ?? null,

      url: getFirstValue(
        incomingRecord.url,
        incomingRecord.source_url
      ),

      dates: incomingDates,

      fields: Object.fromEntries(
        COMPARISON_FIELDS.map(field => [
          field,
          getFieldValue(incomingRecord, field),
        ])
      ),

      evidence_snippets: extractEvidenceSnippets(
        incomingRawContent,
        incomingSearchValues
      ),

      raw_content: incomingRawContent,
    },
  };

  return {
    json: {
      ...data,

      /*
       * DeepSeek Body에서 사용할 최종 비교자료
       */
      verification_context: verificationContext,

      /*
       * 기존 이름도 최신 보강자료로 교체해 둔다.
       */
      deepseek_context: {
        existing: verificationContext.existing,
        incoming: verificationContext.incoming,
      },

      conflict_details: conflictDetails,
      field_comparison: fieldComparison,
    },
  };
});

const allowedActions = new Set([
  'update',
  'keep_existing',
  'review',
]);

const allowedConfidence = new Set([
  'high',
  'medium',
  'low',
]);

const allowedDifferenceTypes = new Set([
  'meaningful_change',
  'enrichment',
  'equivalent_expression',
  'insufficient_evidence',
]);

const allowedFields = new Set([
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
]);

function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function hasText(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

function nullableText(value) {
  return hasText(value) ? value.trim() : null;
}

return $input.all().map((item, index) => {
  // HTTP 노드가 응답 본문만 반환하거나
  // 전체 응답의 body 안에 반환하는 경우를 처리한다.
  let response = item.json.body ?? item.json;

  if (typeof response === 'string') {
    try {
      response = JSON.parse(response);
    } catch {
      throw new Error(
        `아이템 ${index + 1}: HTTP 응답 본문이 유효한 JSON이 아닙니다.`
      );
    }
  }

  if (response?.error) {
    throw new Error(
      `아이템 ${index + 1}: DeepSeek 요청 오류: ` +
      JSON.stringify(response.error)
    );
  }

  const choice = response?.choices?.[0];

  if (!choice) {
    throw new Error(
      `아이템 ${index + 1}: choices[0]이 없습니다. HTTP 응답을 확인하세요.`
    );
  }

  if (
    choice.finish_reason &&
    choice.finish_reason !== 'stop'
  ) {
    throw new Error(
      `아이템 ${index + 1}: 응답이 정상 완료되지 않았습니다. ` +
      `finish_reason=${choice.finish_reason}`
    );
  }

  const content = choice.message?.content;

  if (!hasText(content)) {
    throw new Error(
      `아이템 ${index + 1}: DeepSeek 응답 content가 비어 있습니다.`
    );
  }

  // 응답 전체를 감싼 코드블록만 제거한다.
  const jsonText = content
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  let result;

  try {
    result = JSON.parse(jsonText);
  } catch {
    throw new Error(
      `아이템 ${index + 1}: DeepSeek 판정 결과를 JSON으로 해석할 수 없습니다.`
    );
  }

  if (!isObject(result)) {
    throw new Error(
      'DeepSeek 판정 결과는 JSON 객체여야 합니다.'
    );
  }

  if (
    typeof result.is_actual_change !== 'boolean' ||
    typeof result.auto_update_allowed !== 'boolean'
  ) {
    throw new Error(
      'is_actual_change와 auto_update_allowed는 boolean이어야 합니다.'
    );
  }

  if (
    !Array.isArray(result.field_decisions) ||
    result.field_decisions.length === 0
  ) {
    throw new Error(
      'field_decisions가 없거나 비어 있습니다.'
    );
  }

  if (!allowedConfidence.has(result.overall_confidence)) {
    throw new Error(
      'overall_confidence는 high, medium, low 중 하나여야 합니다.'
    );
  }

  const seenFields = new Set();

  const decisions = result.field_decisions.map((decision) => {
    if (!isObject(decision)) {
      throw new Error(
        'field_decisions의 각 항목은 객체여야 합니다.'
      );
    }

    const field = decision.field;

    if (!allowedFields.has(field)) {
      throw new Error(
        `판정이 허용되지 않은 필드입니다: ${field}`
      );
    }

    if (seenFields.has(field)) {
      throw new Error(
        `동일한 필드가 중복 판정됐습니다: ${field}`
      );
    }

    seenFields.add(field);

    if (!allowedActions.has(decision.action)) {
      throw new Error(
        `${field}: action 값이 올바르지 않습니다.`
      );
    }

    if (!allowedConfidence.has(decision.confidence)) {
      throw new Error(
        `${field}: confidence 값이 올바르지 않습니다.`
      );
    }

    if (!allowedDifferenceTypes.has(decision.difference_type)) {
      throw new Error(
        `${field}: difference_type 값이 올바르지 않습니다.`
      );
    }

    for (const key of [
      'existing_value',
      'incoming_value',
      'selected_value',
    ]) {
      if (!Object.prototype.hasOwnProperty.call(decision, key)) {
        throw new Error(
          `${field}: ${key}가 누락됐습니다.`
        );
      }
    }

    if (!hasText(decision.reason)) {
      throw new Error(
        `${field}: 판정 이유가 없습니다.`
      );
    }

    return {
      field,
      existing_value: decision.existing_value,
      incoming_value: decision.incoming_value,
      selected_value: decision.selected_value,
      action: decision.action,
      difference_type: decision.difference_type,
      reason: decision.reason.trim(),
      evidence: nullableText(decision.evidence),
      freshness_basis: nullableText(decision.freshness_basis),
      confidence: decision.confidence,
    };
  });

  // 요약 목록은 field_decisions를 기준으로 직접 만든다.
  const changedFields = decisions
    .filter((decision) => decision.action === 'update')
    .map((decision) => decision.field);

  const keptFields = decisions
    .filter((decision) => decision.action === 'keep_existing')
    .map((decision) => decision.field);

  const reviewFields = decisions
    .filter((decision) => decision.action === 'review')
    .map((decision) => decision.field);

  const blockingReasons = [];

  if (reviewFields.length > 0) {
    blockingReasons.push(
      `추가검토 필드: ${reviewFields.join(', ')}`
    );
  }

  for (const decision of decisions) {
    if (decision.action !== 'update') {
      continue;
    }

    if (
      decision.confidence !== 'high' ||
      !decision.evidence ||
      !decision.freshness_basis
    ) {
      blockingReasons.push(
        `${decision.field}: 자동 변경에 필요한 신뢰도 또는 근거 부족`
      );
    }
  }

  if (
    changedFields.length > 0 &&
    !result.is_actual_change
  ) {
    blockingReasons.push(
      'update 판정과 is_actual_change 값이 모순됩니다.'
    );
  }

  if (
    changedFields.length > 0 &&
    !result.auto_update_allowed
  ) {
    blockingReasons.push(
      'DeepSeek가 전체 자동 업데이트를 허용하지 않았습니다.'
    );
  }

  const autoUpdateAllowed =
    result.auto_update_allowed === true &&
    result.is_actual_change === true &&
    changedFields.length > 0 &&
    blockingReasons.length === 0;

  const reviewReasons = [
    nullableText(result.review_reason),
    ...blockingReasons,
  ].filter(Boolean);

  return {
    json: {
      deepseek_result: {
        is_actual_change: result.is_actual_change,

        change_summary:
          nullableText(result.change_summary),

        field_decisions: decisions,

        changed_fields: changedFields,
        kept_fields: keptFields,
        review_fields: reviewFields,

        auto_update_allowed: autoUpdateAllowed,
        overall_confidence: result.overall_confidence,

        review_reason:
          reviewReasons.length > 0
            ? [...new Set(reviewReasons)].join(' / ')
            : null,
      },

      deepseek_parse_ok: true,
    },

    pairedItem: {
      item: index,
    },
  };
});

const CANONICAL_FIELDS = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
];

const ALLOWED_FIELDS = new Set(CANONICAL_FIELDS);

function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function hasText(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    (
      typeof value === 'string' &&
      (
        value.trim() === '' ||
        value.trim().toLowerCase() === 'null' ||
        value.trim().toLowerCase() === 'undefined'
      )
    )
  );
}

/*
 * AI가 반환한 값이 실제 입력값과 같은지 확인한다.
 * 객체 키 순서는 무시하고 배열 순서와 자료형은 유지한다.
 */
function sortObjectKeys(value) {
  if (Array.isArray(value)) {
    return value.map(sortObjectKeys);
  }

  if (isObject(value)) {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [
          key,
          sortObjectKeys(value[key]),
        ])
    );
  }

  return value;
}

function valuesEqual(a, b) {
  return (
    JSON.stringify(sortObjectKeys(a)) ===
    JSON.stringify(sortObjectKeys(b))
  );
}

/*
 * 수정공고 필드 역할분기와 동일한 정규화·해시 방식.
 */
function normalize(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (Array.isArray(value)) {
    return JSON.stringify(
      value.map(normalize).sort()
    );
  }

  if (typeof value === 'object') {
    const sorted = {};

    for (const key of Object.keys(value).sort()) {
      sorted[key] = normalize(value[key]);
    }

    return JSON.stringify(sorted);
  }

  return String(value)
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

function fnv1a64(text) {
  let hash = BigInt('0xcbf29ce484222325');
  const prime = BigInt('0x100000001b3');
  const mask = BigInt('0xffffffffffffffff');

  for (const character of text) {
    hash ^= BigInt(character.codePointAt(0));
    hash = (hash * prime) & mask;
  }

  return hash.toString(16).padStart(16, '0');
}

return $input.all().map((item, index) => {
  const current = item.json;
  const result = current.deepseek_result;
  const conflicts = current.conflicting_fields;

  if (!isObject(current.canonical_record)) {
    throw new Error(
      'canonical_record가 없습니다. 수정공고 딥시크 결과 병합을 확인하세요.'
    );
  }

  const noticeId = current.canonical_record.id;

  if (isEmpty(noticeId)) {
    throw new Error(
      'canonical_record.id가 없습니다.'
    );
  }

  if (
    current.merge_notice_id != null &&
    current.merge_notice_id !== noticeId
  ) {
    throw new Error(
      'merge_notice_id와 canonical_record.id가 다릅니다.'
    );
  }

  if (
    !isObject(current.source_record) ||
    current.source_record.notice_id !== noticeId
  ) {
    throw new Error(
      'source_record가 없거나 notice_id가 기존 공고 ID와 다릅니다.'
    );
  }

  if (
    !Array.isArray(conflicts) ||
    conflicts.length === 0
  ) {
    throw new Error(
      '원래 충돌 필드 목록이 없습니다.'
    );
  }

  if (
    current.deepseek_parse_ok !== true ||
    !isObject(result) ||
    !Array.isArray(result.field_decisions)
  ) {
    throw new Error(
      '파싱된 DeepSeek 결과가 없습니다. 결과 병합을 확인하세요.'
    );
  }

  /*
   * 앞에서 보완한 빈 필드, source_keys,
   * 기존 ID와 first_seen_at을 그대로 유지한다.
   */
  const finalRecord = {
    ...current.canonical_record,
  };

  delete finalRecord.created_at;

  const conflictMap = new Map();

  for (const conflict of conflicts) {
    if (
      !isObject(conflict) ||
      !ALLOWED_FIELDS.has(conflict.field) ||
      conflictMap.has(conflict.field)
    ) {
      throw new Error(
        '원래 충돌 목록에 허용되지 않은 필드 또는 중복 필드가 있습니다.'
      );
    }

    if (
      conflict.existing_value === undefined ||
      conflict.incoming_value === undefined
    ) {
      throw new Error(
        `${conflict.field}: 원래 충돌값이 누락됐습니다.`
      );
    }

    conflictMap.set(conflict.field, conflict);

    // 각 충돌 필드는 기존값에서 시작한다.
    finalRecord[conflict.field] =
      conflict.existing_value;
  }

  const decisionsByField = new Map();

  const appliedFields = [];
  const keptFields = [];
  const reviewFields = [];
  const rejectedUpdates = [];

  /*
   * 응답을 필드별로 묶는다.
   * 원래 충돌 목록에 없는 필드는 적용하지 않는다.
   */
  for (const decision of result.field_decisions) {
    if (!isObject(decision)) {
      rejectedUpdates.push({
        field: null,
        reason: '판정 항목이 객체가 아님',
      });

      continue;
    }

    const field = decision.field;

    if (!conflictMap.has(field)) {
      rejectedUpdates.push({
        field: field ?? null,
        reason: '원래 충돌 목록에 없는 필드',
      });

      continue;
    }

    if (!decisionsByField.has(field)) {
      decisionsByField.set(field, []);
    }

    decisionsByField.get(field).push(decision);
  }

  function keepForReview(field, original, decision, reason) {
    finalRecord[field] = original.existing_value;

    reviewFields.push({
      field,
      existing_value: original.existing_value,
      incoming_value: original.incoming_value,
      reason,
      evidence: decision?.evidence ?? null,
      freshness_basis:
        decision?.freshness_basis ?? null,
      confidence: decision?.confidence ?? null,
    });
  }

  /*
   * 전체 auto_update_allowed로 차단하지 않는다.
   * 각 필드의 action과 검증 결과에 따라 독립적으로 처리한다.
   */
  for (const [field, original] of conflictMap) {
    const decisions = decisionsByField.get(field) ?? [];

    if (decisions.length !== 1) {
      keepForReview(
        field,
        original,
        null,
        decisions.length === 0
          ? '해당 필드의 판정이 누락됨'
          : '해당 필드의 판정이 중복됨'
      );

      continue;
    }

    const decision = decisions[0];

    // AI가 비교한 값이 실제 입력과 같은지 확인한다.
    if (
      !valuesEqual(
        decision.existing_value,
        original.existing_value
      ) ||
      !valuesEqual(
        decision.incoming_value,
        original.incoming_value
      )
    ) {
      keepForReview(
        field,
        original,
        decision,
        'AI 응답의 비교값이 실제 입력값과 다름'
      );

      continue;
    }

    if (decision.action === 'keep_existing') {
      keptFields.push({
        field,
        value: original.existing_value,
        reason: decision.reason ?? null,
        confidence: decision.confidence ?? null,
      });

      continue;
    }

    if (decision.action === 'review') {
      keepForReview(
        field,
        original,
        decision,
        decision.reason ?? '추가검토 판정'
      );

      continue;
    }

    if (decision.action !== 'update') {
      keepForReview(
        field,
        original,
        decision,
        `알 수 없는 action: ${decision.action}`
      );

      continue;
    }

    const reasons = [];

    if (decision.confidence !== 'high') {
      reasons.push('confidence가 high가 아님');
    }

    if (!hasText(decision.evidence)) {
      reasons.push('evidence가 없음');
    }

    if (!hasText(decision.freshness_basis)) {
      reasons.push('freshness_basis가 없음');
    }

    if (isEmpty(original.incoming_value)) {
      reasons.push('신규값이 비어 있음');
    }

    if (
      !valuesEqual(
        decision.selected_value,
        original.incoming_value
      )
    ) {
      reasons.push('선택값이 실제 신규값과 다름');
    }

    if (reasons.length > 0) {
      keepForReview(
        field,
        original,
        decision,
        reasons.join(' / ')
      );

      continue;
    }

    // 의미상 동일하면 실제 변경으로 처리하지 않는다.
    if (
      normalize(original.existing_value) ===
      normalize(original.incoming_value)
    ) {
      keptFields.push({
        field,
        value: original.existing_value,
        reason: '정규화 후 기존값과 동일함',
        confidence: decision.confidence,
      });

      continue;
    }

    /*
     * 이 필드만 신규값으로 변경한다.
     * 다른 필드의 review 여부는 영향을 주지 않는다.
     * 저장값은 AI가 쓴 값을 복사하지 않고 실제 입력에서 가져온다.
     */
    finalRecord[field] = original.incoming_value;

    appliedFields.push({
      field,
      old_value: original.existing_value,
      new_value: original.incoming_value,
      reason: decision.reason ?? null,
      evidence: decision.evidence,
      freshness_basis: decision.freshness_basis,
      confidence: decision.confidence,
    });
  }

  const enrichedFields = Array.isArray(current.enriched_fields)
    ? current.enriched_fields
    : [];

  const hasMeaningfulUpdate =
    appliedFields.length > 0 ||
    enrichedFields.length > 0;

  /*
   * 충돌값 적용 여부와 관계없이 출처 키와 확인 시각 반영.
   */
  if (Array.isArray(current.merged_source_keys)) {
    finalRecord.source_keys = [
      ...new Set(
        current.merged_source_keys.filter(Boolean)
      ),
    ];
  }

  finalRecord.last_seen_at = new Date().toISOString();

  /*
   * 실제 변경이나 빈 필드 보완이 있을 때만 updated_at 갱신.
   * 그 외에는 앞에서 전달된 기존값을 유지한다.
   */
  if (hasMeaningfulUpdate) {
    finalRecord.updated_at = new Date().toISOString();
  }

  const hashInput = CANONICAL_FIELDS
    .map(
      (field) =>
        `${field}:${normalize(finalRecord[field])}`
    )
    .join('|');

  finalRecord.content_hash = fnv1a64(hashInput);

  const hasReviewFields = reviewFields.length > 0;

  const reviewReasons = [
    ...reviewFields.map(
      (entry) => `${entry.field}: ${entry.reason}`
    ),
    ...rejectedUpdates.map(
      (entry) => `${entry.field ?? '알 수 없는 필드'}: ${entry.reason}`
    ),
  ];

  return {
    json: {
      ...current,

      canonical_record: finalRecord,

      applied_fields: appliedFields,
      kept_fields_result: keptFields,
      review_fields_result: reviewFields,
      rejected_updates: rejectedUpdates,

      deepseek_applied: appliedFields.length > 0,
      has_meaningful_update: hasMeaningfulUpdate,
      has_review_fields: hasReviewFields,

      needs_review:
        hasReviewFields || rejectedUpdates.length > 0,

      review_reason:
        reviewReasons.length > 0
          ? reviewReasons.join(' / ')
          : null,

      // applied인 동시에 needs_review가 true일 수 있다.
      application_status:
        appliedFields.length > 0
          ? 'applied'
          : reviewReasons.length > 0
            ? 'review'
            : 'kept_existing',
    },

    pairedItem: {
      item: index,
    },
  };
});

return $input.all().map((item, index) => {
  return {
    json: item.json.source_record,
    pairedItem: {
      item: index,
    },
  };
});

function emptyToNull(value) {
  if (value === undefined || value === null) {
    return null;
  }

  if (typeof value === 'string') {
    const trimmed = value.trim();

    if (
      trimmed === '' ||
      trimmed.toLowerCase() === 'null' ||
      trimmed.toLowerCase() === 'undefined'
    ) {
      return null;
    }

    return trimmed;
  }

  return value;
}

const now = new Date().toISOString();

return $input.all().map((item, index) => {
  const current = item.json;

  // 정확조회 결과는 notice_sources의 행 배열이다.
  const candidates = Array.isArray(current.exact_candidates)
    ? current.exact_candidates
    : [];

  const validCandidates = candidates.filter(
    (row) => row?.id && emptyToNull(row.notice_id)
  );

  // 여러 출처 기록이 같은 통합공고에 연결되어 있으면
  // 하나의 notice_id로 정리된다.
  const noticeIds = [
    ...new Set(
      validCandidates.map(
        (row) => emptyToNull(row.notice_id)
      )
    ),
  ];

  if (noticeIds.length === 0) {
    throw new Error(
      'exact_candidates에 notice_id가 없습니다. ' +
      '수정공고 정확조회 결과정리와 If4 출력을 확인하세요.'
    );
  }

  // 서로 다른 통합공고가 조회된 경우에만 중단한다.
  // 첫 번째 후보를 임의로 선택하지 않는다.
  if (noticeIds.length > 1) {
    throw new Error(
      '정확제목 조회 결과에 서로 다른 notice_id가 있습니다. ' +
      'exact_candidates의 연결 대상을 확인하세요.'
    );
  }

  const existingNoticeId = noticeIds[0];

  if (!emptyToNull(current.source_key)) {
    throw new Error(
      '새 수정공고의 source_key가 없습니다.'
    );
  }

  return {
    json: {
      ...current,

      existing_notice_id: existingNoticeId,
      merge_notice_id: existingNoticeId,

      source_record: {
        notice_id: existingNoticeId,

        source_key: current.source_key,
        source: emptyToNull(current.source),
        url: emptyToNull(current.url),

        title: emptyToNull(current.title),
        organization:
          emptyToNull(current.organization),

        target: emptyToNull(current.target),
        excluded_target:
          emptyToNull(current.excluded_target),

        region: emptyToNull(current.region),
        field: emptyToNull(current.field),

        published_at:
          emptyToNull(current.published_at),

        source_modified_at:
          emptyToNull(current.source_modified_at),

        start_date:
          emptyToNull(current.start_date),

        deadline:
          emptyToNull(current.deadline),

        start_at:
          emptyToNull(current.start_at),

        deadline_at:
          emptyToNull(current.deadline_at),

        application_method:
          emptyToNull(current.application_method),

        application_url:
          emptyToNull(current.application_url),

        raw_content:
          emptyToNull(current.raw_content),

        content_hash:
          emptyToNull(current.content_hash),

        first_seen_at: now,
        last_seen_at: now,
        updated_at: now,
      },
    },

    pairedItem: {
      item: index,
    },
  };
});

const rows = $input.all();

if (rows.length !== 1 || !rows[0].json?.id) {
  throw new Error(
    '연결할 notices 행을 찾지 못했습니다. ' +
    'merge_notice_id와 notices 조회 설정을 확인하세요.'
  );
}

return [
  {
    json: {
      existing_notice: rows[0].json,
    },
    pairedItem: {
      item: 0,
    },
  },
];

function toArray(value) {
  if (Array.isArray(value)) {
    return value;
  }

  if (value === undefined || value === null) {
    return [];
  }

  if (typeof value === 'string') {
    const trimmed = value.trim();

    if (!trimmed) {
      return [];
    }

    try {
      const parsed = JSON.parse(trimmed);

      if (Array.isArray(parsed)) {
        return parsed;
      }

      if (typeof parsed === 'string' && parsed.trim()) {
        return [parsed];
      }
    } catch {
      return [trimmed];
    }
  }

  throw new Error(
    'existing_notice.source_keys가 예상한 배열 형식이 아닙니다.'
  );
}

return $input.all().map((item, index) => {
  const current = item.json;
  const existingNotice = current.existing_notice;

  if (!existingNotice?.id) {
    throw new Error(
      'existing_notice.id가 없습니다. notices 조회 결과를 확인하세요.'
    );
  }

  if (
    !current.merge_notice_id ||
    current.merge_notice_id !== existingNotice.id
  ) {
    throw new Error(
      'merge_notice_id와 existing_notice.id가 일치하지 않습니다.'
    );
  }

  if (
    typeof current.source_key !== 'string' ||
    !current.source_key.trim()
  ) {
    throw new Error(
      '새 수정공고의 source_key가 없습니다.'
    );
  }

  // 조회되지 않은 필드를 빈 배열로 취급하면
  // 기존 출처 연결을 누락할 수 있으므로 확인한다.
  if (existingNotice.source_keys === undefined) {
    throw new Error(
      '기존 notices 조회 결과에 source_keys가 없습니다.'
    );
  }

  const existingSourceKeys = toArray(
    existingNotice.source_keys
  );

  const mergedSourceKeys = [
    ...new Set(
      [
        ...existingSourceKeys,
        current.source_key,
      ].filter(
        (value) =>
          typeof value === 'string' &&
          value.trim() !== ''
      )
    ),
  ];

  return {
    json: {
      ...current,

      existing_notice_id: existingNotice.id,
      merge_notice_id: existingNotice.id,
      merged_source_keys: mergedSourceKeys,
    },

    pairedItem: {
      item: index,
    },
  };
});

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    (
      typeof value === 'string' &&
      (
        value.trim() === '' ||
        value.trim().toLowerCase() === 'null' ||
        value.trim().toLowerCase() === 'undefined'
      )
    )
  );
}

function normalize(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (Array.isArray(value)) {
    return JSON.stringify(
      value.map(normalize).sort()
    );
  }

  if (typeof value === 'object') {
    const sorted = {};

    for (const key of Object.keys(value).sort()) {
      sorted[key] = normalize(value[key]);
    }

    return JSON.stringify(sorted);
  }

  return String(value)
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

function fnv1a64(text) {
  let hash = BigInt('0xcbf29ce484222325');
  const prime = BigInt('0x100000001b3');
  const mask = BigInt('0xffffffffffffffff');

  for (const character of text) {
    hash ^= BigInt(character.codePointAt(0));
    hash = (hash * prime) & mask;
  }

  return hash.toString(16).padStart(16, '0');
}

/*
 * 기존값은 다음 두 형태를 지원한다.
 * - existing_notice.title
 * - existing_title
 *
 * current.title 등은 신규 공고값이므로
 * 기존값 조회에 사용하지 않는다.
 */
function getExistingValue(current, field) {
  const nested = current.existing_notice;

  if (
    nested &&
    Object.prototype.hasOwnProperty.call(nested, field) &&
    nested[field] !== undefined
  ) {
    return nested[field];
  }

  const prefixedField = `existing_${field}`;

  if (
    Object.prototype.hasOwnProperty.call(
      current,
      prefixedField
    )
  ) {
    return current[prefixedField];
  }

  return undefined;
}

const comparisonFields = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
];

const now = new Date().toISOString();

return $input.all().map((item, index) => {
  const current = item.json;

  const existingNoticeId = [
    current.merge_notice_id,
    current.existing_notice_id,
    current.existing_notice?.id,
    current.existing_id,
  ].find((value) => !isEmpty(value));

  if (isEmpty(existingNoticeId)) {
    throw new Error(
      '기존 공고 ID가 없습니다. 수정공고 연결정보 출력을 확인하세요.'
    );
  }

  /*
   * 조회되지 않은 필드(undefined)와
   * 조회됐지만 비어 있는 필드(null)를 구분한다.
   */
  const existing = {
    id: existingNoticeId,
  };

  const missingFields = [];

  for (const field of comparisonFields) {
    const value = getExistingValue(current, field);

    if (value === undefined) {
      missingFields.push(field);
    } else {
      existing[field] = value;
    }
  }

  if (missingFields.length > 0) {
    throw new Error(
      '기존 공고 조회 결과에 다음 필드가 누락됐습니다: ' +
      missingFields.join(', ') +
      '. 정확일치 기존 notices 조회와 Merge7 출력을 확인하세요.'
    );
  }

  /*
   * 통합공고 저장 대상.
   * 기존 ID와 비교 필드의 기존값으로 시작한다.
   * created_at은 생성하지 않는다.
   */
  const canonicalRecord = {
    ...existing,
    last_seen_at: now,
  };

  /*
   * 기존 first_seen_at, updated_at을 그대로 유지한다.
   * 조회 결과에 없으면 저장 데이터에서도 제외하여
   * DB의 기존값을 덮어쓰지 않는다.
   */
  for (const field of ['first_seen_at', 'updated_at']) {
    const value = getExistingValue(current, field);

    if (value !== undefined) {
      canonicalRecord[field] = value;
    }
  }

  /*
   * 연결정보 노드에서 합친 출처 키 목록을 반영한다.
   */
  const sourceKeys =
    current.merged_source_keys ??
    getExistingValue(current, 'source_keys');

  if (sourceKeys !== undefined) {
    canonicalRecord.source_keys = sourceKeys;
  }

  const enrichedFields = [];
  const conflictingFields = [];

  for (const field of comparisonFields) {
    const existingValue = existing[field];
    const incomingValue = current[field];

    // 기존값이 비어 있고 신규값이 있으면 보완한다.
    if (
      isEmpty(existingValue) &&
      !isEmpty(incomingValue)
    ) {
      canonicalRecord[field] = incomingValue;

      enrichedFields.push({
        field,
        old_value: existingValue ?? null,
        new_value: incomingValue,
      });

      continue;
    }

    // 신규값이 비어 있으면 기존값을 유지한다.
    if (isEmpty(incomingValue)) {
      continue;
    }

    // 양쪽에 값이 있고 다르면 충돌로 기록한다.
    // 이 단계에서는 신규값으로 덮어쓰지 않는다.
    if (
      !isEmpty(existingValue) &&
      normalize(existingValue) !== normalize(incomingValue)
    ) {
      conflictingFields.push({
        field,
        existing_value: existingValue,
        incoming_value: incomingValue,
      });
    }
  }

  let mergeStatus = 'same';

  if (conflictingFields.length > 0) {
    mergeStatus = 'conflict';
  } else if (enrichedFields.length > 0) {
    mergeStatus = 'enriched';
  }

  const hashInput = comparisonFields
    .map(
      (field) =>
        `${field}:${normalize(canonicalRecord[field])}`
    )
    .join('|');

  canonicalRecord.content_hash = fnv1a64(hashInput);

  /*
   * 실제로 빈 필드를 보완했을 때만 updated_at 갱신.
   * same에서는 기존값 유지.
   * 충돌값의 채택에 따른 갱신은 뒤의 판단 적용 노드에서 처리.
   */
  if (enrichedFields.length > 0) {
    canonicalRecord.updated_at = now;
  }

  return {
    json: {
      ...current,

      merge_notice_id: existingNoticeId,
      merge_status: mergeStatus,

      enriched_fields: enrichedFields,
      conflicting_fields: conflictingFields,

      canonical_record: canonicalRecord,

      deepseek_context: {
        existing: {
          notice_id: existingNoticeId,

          source:
            getExistingValue(current, 'source') ?? null,

          source_key:
            getExistingValue(current, 'source_key') ?? null,

          url:
            getExistingValue(current, 'url') ?? null,

          raw_content:
            getExistingValue(current, 'raw_content') ?? null,

          source_modified_at:
            getExistingValue(
              current,
              'source_modified_at'
            ) ?? null,

          values: Object.fromEntries(
            comparisonFields.map((field) => [
              field,
              existing[field] ?? null,
            ])
          ),
        },

        incoming: {
          source: current.source ?? null,
          source_key: current.source_key ?? null,
          url: current.url ?? null,
          raw_content: current.raw_content ?? null,

          source_modified_at:
            current.source_modified_at ?? null,

          values: Object.fromEntries(
            comparisonFields.map((field) => [
              field,
              current[field] ?? null,
            ])
          ),
        },

        conflicting_fields: conflictingFields,
      },
    },

    pairedItem: {
      item: index,
    },
  };
});

return $input.all().map((item, index) => {
  const record = item.json.canonical_record;

  if (!record?.id) {
    throw new Error(
      'canonical_record.id가 없습니다. 역할분기 출력을 확인하세요.'
    );
  }

  return {
    json: {
      ...record,
    },
    pairedItem: {
      item: index,
    },
  };
});

return $input.all().map((item, index) => {
  const current = item.json;
  const context = current.deepseek_context;

  if (!current.canonical_record?.id) {
    throw new Error(
      'canonical_record.id가 없습니다. ' +
      '정확일치 필드 역할분기 출력을 확인하세요.'
    );
  }

  if (!context?.existing || !context?.incoming) {
    throw new Error(
      'deepseek_context의 existing 또는 incoming이 없습니다. ' +
      '정확일치 필드 역할분기 출력을 확인하세요.'
    );
  }

  if (
    !Array.isArray(current.conflicting_fields) ||
    current.conflicting_fields.length === 0
  ) {
    throw new Error(
      '충돌 필드가 없습니다. ' +
      '정확일치 비교결과 분기의 conflict 출력 연결을 확인하세요.'
    );
  }

  return {
    json: {
      // 기존 ID, source_record, 보완된 저장값 등을 유지
      ...current,

      // 다음 DeepSeek 노드에 전달할 판단 자료
      conflict_judgment_input: {
        notice_id: current.canonical_record.id,

        existing: context.existing,
        incoming: context.incoming,

        // 판단 대상은 실제 충돌한 필드만
        conflicting_fields: current.conflicting_fields,
      },
    },

    pairedItem: {
      item: index,
    },
  };
});

const allowedActions = new Set([
  'update',
  'keep_existing',
  'review',
]);

const allowedConfidence = new Set([
  'high',
  'medium',
  'low',
]);

const allowedDifferenceTypes = new Set([
  'meaningful_change',
  'enrichment',
  'equivalent_expression',
  'insufficient_evidence',
]);

const allowedFields = new Set([
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
]);

function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function hasText(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

function nullableText(value) {
  return hasText(value) ? value.trim() : null;
}

return $input.all().map((item, index) => {
  // HTTP 노드가 응답 본문만 반환하거나
  // 전체 응답의 body 안에 반환하는 경우를 처리한다.
  let response = item.json.body ?? item.json;

  if (typeof response === 'string') {
    try {
      response = JSON.parse(response);
    } catch {
      throw new Error(
        `아이템 ${index + 1}: HTTP 응답 본문이 유효한 JSON이 아닙니다.`
      );
    }
  }

  if (response?.error) {
    throw new Error(
      `아이템 ${index + 1}: DeepSeek 요청 오류: ` +
      JSON.stringify(response.error)
    );
  }

  const choice = response?.choices?.[0];

  if (!choice) {
    throw new Error(
      `아이템 ${index + 1}: choices[0]이 없습니다. HTTP 응답을 확인하세요.`
    );
  }

  if (
    choice.finish_reason &&
    choice.finish_reason !== 'stop'
  ) {
    throw new Error(
      `아이템 ${index + 1}: 응답이 정상 완료되지 않았습니다. ` +
      `finish_reason=${choice.finish_reason}`
    );
  }

  const content = choice.message?.content;

  if (!hasText(content)) {
    throw new Error(
      `아이템 ${index + 1}: DeepSeek 응답 content가 비어 있습니다.`
    );
  }

  // 응답 전체를 감싼 코드블록만 제거한다.
  const jsonText = content
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();

  let result;

  try {
    result = JSON.parse(jsonText);
  } catch {
    throw new Error(
      `아이템 ${index + 1}: DeepSeek 판정 결과를 JSON으로 해석할 수 없습니다.`
    );
  }

  if (!isObject(result)) {
    throw new Error(
      'DeepSeek 판정 결과는 JSON 객체여야 합니다.'
    );
  }

  if (
    typeof result.is_actual_change !== 'boolean' ||
    typeof result.auto_update_allowed !== 'boolean'
  ) {
    throw new Error(
      'is_actual_change와 auto_update_allowed는 boolean이어야 합니다.'
    );
  }

  if (
    !Array.isArray(result.field_decisions) ||
    result.field_decisions.length === 0
  ) {
    throw new Error(
      'field_decisions가 없거나 비어 있습니다.'
    );
  }

  if (!allowedConfidence.has(result.overall_confidence)) {
    throw new Error(
      'overall_confidence는 high, medium, low 중 하나여야 합니다.'
    );
  }

  const seenFields = new Set();

  const decisions = result.field_decisions.map((decision) => {
    if (!isObject(decision)) {
      throw new Error(
        'field_decisions의 각 항목은 객체여야 합니다.'
      );
    }

    const field = decision.field;

    if (!allowedFields.has(field)) {
      throw new Error(
        `판정이 허용되지 않은 필드입니다: ${field}`
      );
    }

    if (seenFields.has(field)) {
      throw new Error(
        `동일한 필드가 중복 판정됐습니다: ${field}`
      );
    }

    seenFields.add(field);

    if (!allowedActions.has(decision.action)) {
      throw new Error(
        `${field}: action 값이 올바르지 않습니다.`
      );
    }

    if (!allowedConfidence.has(decision.confidence)) {
      throw new Error(
        `${field}: confidence 값이 올바르지 않습니다.`
      );
    }

    if (!allowedDifferenceTypes.has(decision.difference_type)) {
      throw new Error(
        `${field}: difference_type 값이 올바르지 않습니다.`
      );
    }

    for (const key of [
      'existing_value',
      'incoming_value',
      'selected_value',
    ]) {
      if (!Object.prototype.hasOwnProperty.call(decision, key)) {
        throw new Error(
          `${field}: ${key}가 누락됐습니다.`
        );
      }
    }

    if (!hasText(decision.reason)) {
      throw new Error(
        `${field}: 판정 이유가 없습니다.`
      );
    }

    return {
      field,
      existing_value: decision.existing_value,
      incoming_value: decision.incoming_value,
      selected_value: decision.selected_value,
      action: decision.action,
      difference_type: decision.difference_type,
      reason: decision.reason.trim(),
      evidence: nullableText(decision.evidence),
      freshness_basis: nullableText(decision.freshness_basis),
      confidence: decision.confidence,
    };
  });

  // 요약 목록은 field_decisions를 기준으로 직접 만든다.
  const changedFields = decisions
    .filter((decision) => decision.action === 'update')
    .map((decision) => decision.field);

  const keptFields = decisions
    .filter((decision) => decision.action === 'keep_existing')
    .map((decision) => decision.field);

  const reviewFields = decisions
    .filter((decision) => decision.action === 'review')
    .map((decision) => decision.field);

  const blockingReasons = [];

  if (reviewFields.length > 0) {
    blockingReasons.push(
      `추가검토 필드: ${reviewFields.join(', ')}`
    );
  }

  for (const decision of decisions) {
    if (decision.action !== 'update') {
      continue;
    }

    if (
      decision.confidence !== 'high' ||
      !decision.evidence ||
      !decision.freshness_basis
    ) {
      blockingReasons.push(
        `${decision.field}: 자동 변경에 필요한 신뢰도 또는 근거 부족`
      );
    }
  }

  if (
    changedFields.length > 0 &&
    !result.is_actual_change
  ) {
    blockingReasons.push(
      'update 판정과 is_actual_change 값이 모순됩니다.'
    );
  }

  if (
    changedFields.length > 0 &&
    !result.auto_update_allowed
  ) {
    blockingReasons.push(
      'DeepSeek가 전체 자동 업데이트를 허용하지 않았습니다.'
    );
  }

  const autoUpdateAllowed =
    result.auto_update_allowed === true &&
    result.is_actual_change === true &&
    changedFields.length > 0 &&
    blockingReasons.length === 0;

  const reviewReasons = [
    nullableText(result.review_reason),
    ...blockingReasons,
  ].filter(Boolean);

  return {
    json: {
      deepseek_result: {
        is_actual_change: result.is_actual_change,

        change_summary:
          nullableText(result.change_summary),

        field_decisions: decisions,

        changed_fields: changedFields,
        kept_fields: keptFields,
        review_fields: reviewFields,

        auto_update_allowed: autoUpdateAllowed,
        overall_confidence: result.overall_confidence,

        review_reason:
          reviewReasons.length > 0
            ? [...new Set(reviewReasons)].join(' / ')
            : null,
      },

      deepseek_parse_ok: true,
    },

    pairedItem: {
      item: index,
    },
  };
});

const CANONICAL_FIELDS = [
  'title',
  'organization',
  'target',
  'excluded_target',
  'region',
  'field',
  'published_at',
  'start_date',
  'start_at',
  'deadline',
  'deadline_at',
  'application_method',
  'application_url',
];

const ALLOWED_FIELDS = new Set(CANONICAL_FIELDS);

function isObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function hasText(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

function isEmpty(value) {
  return (
    value === null ||
    value === undefined ||
    (
      typeof value === 'string' &&
      (
        value.trim() === '' ||
        value.trim().toLowerCase() === 'null' ||
        value.trim().toLowerCase() === 'undefined'
      )
    )
  );
}

/*
 * AI가 반환한 값이 실제 입력값과 같은지 확인한다.
 * 객체 키 순서는 무시하고 배열 순서와 자료형은 유지한다.
 */
function sortObjectKeys(value) {
  if (Array.isArray(value)) {
    return value.map(sortObjectKeys);
  }

  if (isObject(value)) {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [
          key,
          sortObjectKeys(value[key]),
        ])
    );
  }

  return value;
}

function valuesEqual(a, b) {
  return (
    JSON.stringify(sortObjectKeys(a)) ===
    JSON.stringify(sortObjectKeys(b))
  );
}

/*
 * 수정공고 필드 역할분기와 동일한 정규화·해시 방식.
 */
function normalize(value) {
  if (value === null || value === undefined) {
    return '';
  }

  if (Array.isArray(value)) {
    return JSON.stringify(
      value.map(normalize).sort()
    );
  }

  if (typeof value === 'object') {
    const sorted = {};

    for (const key of Object.keys(value).sort()) {
      sorted[key] = normalize(value[key]);
    }

    return JSON.stringify(sorted);
  }

  return String(value)
    .normalize('NFKC')
    .replace(/\s+/g, ' ')
    .trim();
}

function fnv1a64(text) {
  let hash = BigInt('0xcbf29ce484222325');
  const prime = BigInt('0x100000001b3');
  const mask = BigInt('0xffffffffffffffff');

  for (const character of text) {
    hash ^= BigInt(character.codePointAt(0));
    hash = (hash * prime) & mask;
  }

  return hash.toString(16).padStart(16, '0');
}

return $input.all().map((item, index) => {
  const current = item.json;
  const result = current.deepseek_result;
  const conflicts = current.conflicting_fields;

  if (!isObject(current.canonical_record)) {
    throw new Error(
      'canonical_record가 없습니다. 수정공고 딥시크 결과 병합을 확인하세요.'
    );
  }

  const noticeId = current.canonical_record.id;

  if (isEmpty(noticeId)) {
    throw new Error(
      'canonical_record.id가 없습니다.'
    );
  }

  if (
    current.merge_notice_id != null &&
    current.merge_notice_id !== noticeId
  ) {
    throw new Error(
      'merge_notice_id와 canonical_record.id가 다릅니다.'
    );
  }

  if (
    !isObject(current.source_record) ||
    current.source_record.notice_id !== noticeId
  ) {
    throw new Error(
      'source_record가 없거나 notice_id가 기존 공고 ID와 다릅니다.'
    );
  }

  if (
    !Array.isArray(conflicts) ||
    conflicts.length === 0
  ) {
    throw new Error(
      '원래 충돌 필드 목록이 없습니다.'
    );
  }

  if (
    current.deepseek_parse_ok !== true ||
    !isObject(result) ||
    !Array.isArray(result.field_decisions)
  ) {
    throw new Error(
      '파싱된 DeepSeek 결과가 없습니다. 결과 병합을 확인하세요.'
    );
  }

  /*
   * 앞에서 보완한 빈 필드, source_keys,
   * 기존 ID와 first_seen_at을 그대로 유지한다.
   */
  const finalRecord = {
    ...current.canonical_record,
  };

  delete finalRecord.created_at;

  const conflictMap = new Map();

  for (const conflict of conflicts) {
    if (
      !isObject(conflict) ||
      !ALLOWED_FIELDS.has(conflict.field) ||
      conflictMap.has(conflict.field)
    ) {
      throw new Error(
        '원래 충돌 목록에 허용되지 않은 필드 또는 중복 필드가 있습니다.'
      );
    }

    if (
      conflict.existing_value === undefined ||
      conflict.incoming_value === undefined
    ) {
      throw new Error(
        `${conflict.field}: 원래 충돌값이 누락됐습니다.`
      );
    }

    conflictMap.set(conflict.field, conflict);

    // 각 충돌 필드는 기존값에서 시작한다.
    finalRecord[conflict.field] =
      conflict.existing_value;
  }

  const decisionsByField = new Map();

  const appliedFields = [];
  const keptFields = [];
  const reviewFields = [];
  const rejectedUpdates = [];

  /*
   * 응답을 필드별로 묶는다.
   * 원래 충돌 목록에 없는 필드는 적용하지 않는다.
   */
  for (const decision of result.field_decisions) {
    if (!isObject(decision)) {
      rejectedUpdates.push({
        field: null,
        reason: '판정 항목이 객체가 아님',
      });

      continue;
    }

    const field = decision.field;

    if (!conflictMap.has(field)) {
      rejectedUpdates.push({
        field: field ?? null,
        reason: '원래 충돌 목록에 없는 필드',
      });

      continue;
    }

    if (!decisionsByField.has(field)) {
      decisionsByField.set(field, []);
    }

    decisionsByField.get(field).push(decision);
  }

  function keepForReview(field, original, decision, reason) {
    finalRecord[field] = original.existing_value;

    reviewFields.push({
      field,
      existing_value: original.existing_value,
      incoming_value: original.incoming_value,
      reason,
      evidence: decision?.evidence ?? null,
      freshness_basis:
        decision?.freshness_basis ?? null,
      confidence: decision?.confidence ?? null,
    });
  }

  /*
   * 전체 auto_update_allowed로 차단하지 않는다.
   * 각 필드의 action과 검증 결과에 따라 독립적으로 처리한다.
   */
  for (const [field, original] of conflictMap) {
    const decisions = decisionsByField.get(field) ?? [];

    if (decisions.length !== 1) {
      keepForReview(
        field,
        original,
        null,
        decisions.length === 0
          ? '해당 필드의 판정이 누락됨'
          : '해당 필드의 판정이 중복됨'
      );

      continue;
    }

    const decision = decisions[0];

    // AI가 비교한 값이 실제 입력과 같은지 확인한다.
    if (
      !valuesEqual(
        decision.existing_value,
        original.existing_value
      ) ||
      !valuesEqual(
        decision.incoming_value,
        original.incoming_value
      )
    ) {
      keepForReview(
        field,
        original,
        decision,
        'AI 응답의 비교값이 실제 입력값과 다름'
      );

      continue;
    }

    if (decision.action === 'keep_existing') {
      keptFields.push({
        field,
        value: original.existing_value,
        reason: decision.reason ?? null,
        confidence: decision.confidence ?? null,
      });

      continue;
    }

    if (decision.action === 'review') {
      keepForReview(
        field,
        original,
        decision,
        decision.reason ?? '추가검토 판정'
      );

      continue;
    }

    if (decision.action !== 'update') {
      keepForReview(
        field,
        original,
        decision,
        `알 수 없는 action: ${decision.action}`
      );

      continue;
    }

    const reasons = [];

    if (decision.confidence !== 'high') {
      reasons.push('confidence가 high가 아님');
    }

    if (!hasText(decision.evidence)) {
      reasons.push('evidence가 없음');
    }

    if (!hasText(decision.freshness_basis)) {
      reasons.push('freshness_basis가 없음');
    }

    if (isEmpty(original.incoming_value)) {
      reasons.push('신규값이 비어 있음');
    }

    if (
      !valuesEqual(
        decision.selected_value,
        original.incoming_value
      )
    ) {
      reasons.push('선택값이 실제 신규값과 다름');
    }

    if (reasons.length > 0) {
      keepForReview(
        field,
        original,
        decision,
        reasons.join(' / ')
      );

      continue;
    }

    // 의미상 동일하면 실제 변경으로 처리하지 않는다.
    if (
      normalize(original.existing_value) ===
      normalize(original.incoming_value)
    ) {
      keptFields.push({
        field,
        value: original.existing_value,
        reason: '정규화 후 기존값과 동일함',
        confidence: decision.confidence,
      });

      continue;
    }

    /*
     * 이 필드만 신규값으로 변경한다.
     * 다른 필드의 review 여부는 영향을 주지 않는다.
     * 저장값은 AI가 쓴 값을 복사하지 않고 실제 입력에서 가져온다.
     */
    finalRecord[field] = original.incoming_value;

    appliedFields.push({
      field,
      old_value: original.existing_value,
      new_value: original.incoming_value,
      reason: decision.reason ?? null,
      evidence: decision.evidence,
      freshness_basis: decision.freshness_basis,
      confidence: decision.confidence,
    });
  }

  const enrichedFields = Array.isArray(current.enriched_fields)
    ? current.enriched_fields
    : [];

  const hasMeaningfulUpdate =
    appliedFields.length > 0 ||
    enrichedFields.length > 0;

  /*
   * 충돌값 적용 여부와 관계없이 출처 키와 확인 시각 반영.
   */
  if (Array.isArray(current.merged_source_keys)) {
    finalRecord.source_keys = [
      ...new Set(
        current.merged_source_keys.filter(Boolean)
      ),
    ];
  }

  finalRecord.last_seen_at = new Date().toISOString();

  /*
   * 실제 변경이나 빈 필드 보완이 있을 때만 updated_at 갱신.
   * 그 외에는 앞에서 전달된 기존값을 유지한다.
   */
  if (hasMeaningfulUpdate) {
    finalRecord.updated_at = new Date().toISOString();
  }

  const hashInput = CANONICAL_FIELDS
    .map(
      (field) =>
        `${field}:${normalize(finalRecord[field])}`
    )
    .join('|');

  finalRecord.content_hash = fnv1a64(hashInput);

  const hasReviewFields = reviewFields.length > 0;

  const reviewReasons = [
    ...reviewFields.map(
      (entry) => `${entry.field}: ${entry.reason}`
    ),
    ...rejectedUpdates.map(
      (entry) => `${entry.field ?? '알 수 없는 필드'}: ${entry.reason}`
    ),
  ];

  return {
    json: {
      ...current,

      canonical_record: finalRecord,

      applied_fields: appliedFields,
      kept_fields_result: keptFields,
      review_fields_result: reviewFields,
      rejected_updates: rejectedUpdates,

